L["The shortest walk. Cuts across fields and goes straight over hills."] = "En kısa yürüyüş. Tarlaların içinden kestirir, tepelerin üstünden dümdüz geçer."
L["Takes roads when they aren't much longer, and goes round steep hills."] = "Çok uzun değilse yolları kullanır, dik tepelerin çevresinden dolaşır."
L["Stays on roads, even when it's longer. Slower, but easy to follow."] = "Daha uzun olsa da yollardan ayrılmaz. Daha yavaş ama izlemesi kolay."
L["Every style keeps you out of the other faction's towns and away from zones far above your level."] = "Her stil seni diğer tarafın kasabalarından ve seviyenin çok üstündeki bölgelerden uzak tutar."
L["Supplies"] = "Malzemeler"
L["your next stop"] = "sıradaki durağın"
L["Points the way. The map marks each place."] = "Yolu gösterir. Harita her yeri işaretler."
