L["Skip keeps these as they are."] = "Atla, bunları olduğu gibi bırakır."
L["How the arrow walks you. Change it any time in Options."] = "Okun seni nasıl yürüteceği. İstediğin zaman Seçenekler'den değiştir."
L["%s opens the guide window on the right. The arrow points at your first stop."] = "%s, sağda rehber penceresini açar. Ok ilk durağını gösterir."
L["Played to the end in tests, but not yet by players. If a step is wrong, press %s in the guide window and tell us on Discord."] = "Testlerde sonuna kadar oynandı, ama henüz oyuncular oynamadı. Bir adım yanlışsa rehber penceresinde %s düğmesine bas ve Discord'da bize söyle."
L["Feedback, bug reports and news."] = "Geri bildirim, hata bildirimleri ve haberler."
L["Guides by other players, installed like any addon. They show under Community guides in the guide list."] = "Başka oyuncuların rehberleri, her eklenti gibi kurulur. Rehber listesinde Topluluk rehberleri altında görünürler."
L["A few choices to start with. Everything else is in %s."] = "Başlangıç için birkaç seçim. Geri kalan her şey burada: %s."
L["Route line"] = "Rota çizgisi"
L["How the way to your goal shows on the world map and the minimap. The line is the easiest to follow; sparkles show as dots while Reduce motion is on."] = "Hedefine giden yolun dünya haritasında ve mini haritada nasıl görüneceği. Çizgiyi izlemek en kolayıdır; Hareketi azalt açıkken ışıltılar nokta olarak görünür."

