L["Hides Polestar's arrow in favour of TomTom's, except on the way to another continent, where TomTom's arrow cannot point."] = "Polestar'ın okunu gizleyip TomTom'unkini kullanır; TomTom'un okunun gösteremediği başka bir kıtaya giden yol hariç."
L["Automation"] = "Otomasyon"
