L["The accent follows your class: warlock purple, shaman blue, druid orange. Picking your own accent turns this off."] = "Vurgu sınıfını izler: Warlock mor, Shaman mavi, Druid turuncu. Kendi vurgunu seçmek bunu kapatır."
