L["Background opacity"] = "Arka plan opaklığı"
L["The background opacity of every Polestar window: how much of the world shows through. Right-click to reset."] = "Her Polestar penceresinin arka plan opaklığı: dünyanın ne kadarının arkadan göründüğü. Sıfırlamak için sağ tıkla."
