L["Write quests, routes and world data for guide authors. Off until you start it."] = "Rehber yazarları için görevleri, rotaları ve dünya verisini kaydeder. Sen başlatana dek kapalı."
L["Print status"] = "Durumu yazdır"
L["The Polestar Recorder addon is not loaded. Enable it in the AddOns list on the character screen to record your play for guide authoring."] = "Polestar Recorder eklentisi yüklü değil. Rehber yazımı için oyununu kaydetmek istiyorsan karakter ekranındaki AddOns listesinde etkinleştir."
L["Recording"] = "Kaydediliyor"
L["Stop recording"] = "Kaydı durdur"
L["Nothing more is written until you start it again."] = "Yeniden başlatana dek başka bir şey kaydedilmez."
L["A community project"] = "Bir topluluk projesi"
L["Leveling guides for World of Warcraft: Forever."] = "World of Warcraft: Forever için seviye rehberleri."
L["Version"] = "Sürüm"
L["Why Polestar"] = "Neden Polestar"
L["Leveling guides have become a business: the best routes sit behind subscriptions and paywalls. Polestar goes the other way. It is free, open source under the GPL-3.0, and built by the community that plays it."] = "Seviye rehberleri bir ticarete dönüştü: en iyi rotalar aboneliklerin ve ödeme duvarlarının arkasında. Polestar tersini yapıyor. Ücretsiz, GPL-3.0 ile açık kaynak ve onu oynayan topluluk tarafından yapılıyor."
L["Polestar doesn't claim to be the fastest guide, or the smoothest. It is a free alternative, and it gets better with time."] = "Polestar en hızlı ya da en akıcı rehber olduğunu iddia etmiyor. Ücretsiz bir alternatif ve zamanla daha iyi oluyor."
L["Anyone can read the code, fix a step, sharpen a route or write a new guide, and contributions are welcome. The GPL keeps it that way: every copy and every fork stays open."] = "Herkes kodu okuyabilir, bir adımı düzeltebilir, bir rotayı iyileştirebilir ya da yeni bir rehber yazabilir; katkılar memnuniyetle karşılanır. GPL bunu böyle tutar: her kopya ve her çatal açık kalır."
L["It is young and still in beta, so expect the odd wrong step, waypoint or quest. Every report and every fix tunes it, and together we'll get it where it should be."] = "Daha genç ve hâlâ beta aşamasında; ara sıra yanlış bir adım, yol noktası ya da görev bekleyebilirsin. Her bildirim ve her düzeltme onu iyileştiriyor; birlikte olması gereken yere getireceğiz."
L["Open source and free is the future."] = "Gelecek açık kaynak ve ücretsiz."
L["show or hide the guide window"] = "rehber penceresini göster ya da gizle"
L["choose a guide"] = "bir rehber seç"
L["move through steps"] = "adımlar arasında gezin"
L["report a problem with a step on the Polestar Discord"] = "bir adımla ilgili sorunu Polestar Discord'unda bildir"
L["every command"] = "tüm komutlar"
L["Credits"] = "Emeği geçenler"
L["Inter typeface by The Inter Project Authors, SIL Open Font License 1.1."] = "Inter yazı tipi: The Inter Project Authors, SIL Open Font License 1.1."
L["Wordmark set in Cinzel by The Cinzel Project Authors, SIL Open Font License 1.1."] = "Logo yazısı Cinzel ile dizildi: The Cinzel Project Authors, SIL Open Font License 1.1."
L["Quest and map data includes pfQuest by shagu (MIT License)."] = "Görev ve harita verileri shagu'nun pfQuest'ini içerir (MIT Lisansı)."
L["Discord and its logo are trademarks of Discord Inc.; the logo marks the link to the Polestar Discord."] = "Discord ve logosu Discord Inc.'in ticari markalarıdır; logo Polestar Discord bağlantısını gösterir."
L["With EllesmereUI installed, Polestar can follow its accent, font and panel colour through its public skinning API."] = "EllesmereUI yüklüyse Polestar, onun herkese açık görünüm API'si üzerinden vurgusunu, yazı tipini ve panel rengini izleyebilir."
L["Maintenance"] = "Bakım"
L["Reset all settings"] = "Tüm ayarları sıfırla"
L["Every Polestar setting back to default. Progress is kept."] = "Tüm Polestar ayarları varsayılana döner. İlerleme korunur."
L["Reset positions"] = "Konumları sıfırla"
L["Guide window, arrow and these windows."] = "Rehber penceresi, ok ve bu pencereler."
L["Guides made by other players: switch them on or off, and choose where suggestions come from."] = "Başka oyuncuların yaptığı rehberler: aç ya da kapat, ve önerilerin nereden geleceğini seç."
L["The data recorder for guide authors."] = "Rehber yazarları için veri kaydedici."
L["Why Polestar exists, its commands and its credits."] = "Polestar neden var, komutları ve emeği geçenler."
L["Nothing to set here yet: the module behind this page is not loaded."] = "Burada henüz ayarlanacak bir şey yok: bu sayfanın modülü yüklü değil."
L["No settings match “%s”."] = "“%s” ile eşleşen ayar yok."
L["1 setting matches"] = "1 ayar eşleşiyor"
L["%d settings match"] = "%d ayar eşleşiyor"
L["Reset page"] = "Sayfayı sıfırla"
L["Reload UI"] = "Arayüzü yeniden yükle"
L["Search settings"] = "Ayarlarda ara"
L["Open Polestar settings"] = "Polestar ayarlarını aç"
L["Close the game menu to see Polestar's settings (it cannot be closed for you in combat)."] = "Polestar ayarlarını görmek için oyun menüsünü kapat (savaşta senin yerine kapatılamaz)."
L["Expand step tips"] = "Adım ipuçları açık başlasın"
L["Start each step with its tip in full instead of one line."] = "Her adım, ipucu tek satır yerine tam olarak başlar."
L["Walk real paths"] = "Gerçek yolları yürü"
L["The arrow follows paths on the ground around cliffs, water and walls, on Polestar's walking maps, with Shortest Path Forever's router by Cillian Berragan. Off: it points straight at each stop."] = "Ok, Polestar'ın yürüme haritalarında yerdeki yolları uçurumların, suyun ve duvarların çevresinden izler; Cillian Berragan'ın Shortest Path Forever yönlendiricisiyle. Kapalı: her durağı doğrudan gösterir."
L["Route lines"] = "Rota çizgileri"
L["Class teleports"] = "Sınıf ışınlanmaları"
L["Routes may start with a Teleport spell you know (a mage's city teleports, a druid's Moonglade) when it is faster. A city teleport needs a Rune of Teleportation in your bags."] = "Daha hızlıysa rotalar bildiğin bir Teleport büyüsüyle başlayabilir (Mage'in şehir ışınlanmaları, Druid'in Moonglade'i). Şehir ışınlanması için çantanda Rune of Teleportation gerekir."
L["Share boat times"] = "Gemi saatlerini paylaş"
L["Riding a boat, zeppelin, tram or lift times it; your guild and group get those times and you get theirs, so the arrow can say when the next one leaves."] = "Gemi, zeplin, tramvay ya da asansöre binince süresi ölçülür; loncan ve grubun bu süreleri alır, sen de onlarınkini; böylece ok bir sonrakinin ne zaman kalkacağını söyleyebilir."
L["Warn about missable quests"] = "Kaçırılabilir görevler için uyar"
L["Before you take a quest that closes another for good, says which in chat and leaves the accept to you."] = "Başka bir görevi kalıcı olarak kapatan bir görevi almadan önce hangisi olduğunu sohbette söyler ve almayı sana bırakır."
L["The arrow's target, the stops of its travel route, the step's other goals, the areas their mobs and objects spawn in, and the route lines."] = "Okun hedefi, yolculuk rotasının durakları, adımın diğer hedefleri, yaratıklarının ve nesnelerinin doğduğu alanlar ve rota çizgileri."
L["The arrow's target, the areas it spawns in, and the route line."] = "Okun hedefi, doğduğu alanlar ve rota çizgisi."
L["Moving dots from you to the target on the world map and the minimap, along the travel route, while route lines are off."] = "Rota çizgileri kapalıyken dünya haritasında ve mini haritada, yolculuk rotası boyunca senden hedefe ilerleyen noktalar."
L["Talents"] = "Yetenekler"
L["Talent plan"] = "Yetenek planı"
L["This translation was made with AI. Help improve it on Discord."] = "Bu çeviri yapay zekâ ile yapıldı. Discord'da iyileştirmesine yardım et."
L["Close the game menu to see Polestar's settings."] = "Polestar ayarlarını görmek için oyun menüsünü kapat."
L["Integrations"] = "Entegrasyonlar"
L["Settings for other addons Polestar works with, shown when they are installed."] = "Polestar'ın birlikte çalıştığı diğer eklentilerin ayarları; yüklü olduklarında gösterilir."
L["None of the addons Polestar works with is installed."] = "Polestar'ın birlikte çalıştığı eklentilerin hiçbiri yüklü değil."
L["The skin's font (the default: the game's own, Fira Sans in Halo), or a font of your choice."] = "Görünümün yazı tipi (varsayılan: oyunun kendisi, Halo'da Fira Sans) ya da seçtiğin bir yazı tipi."
L["The skin's font"] = "Görünümün yazı tipi"
L["Skin"] = "Görünüm teması"
L["Polestar's own look (the default), Halo (no frame, a soft dark veil, Fira Sans), Hearth (warm game colours), or the game's own art: WoW Forever, Blizzard and Classic. Style, compact mode and the colours you pick work in each."] = "Polestar'ın kendi görünüşü (varsayılan), Halo (çerçevesiz, yumuşak koyu bir örtü, Fira Sans), Hearth (sıcak oyun renkleri) ya da oyunun kendi çizimleri: WoW Forever, Blizzard ve Classic. Stil, kompakt görünüm ve seçtiğin renkler hepsinde çalışır."
L["The skin's arrow"] = "Görünümün oku"
L["Lock arrow and buttons"] = "Oku ve düğmeleri kilitle"
L["Stops stray drags on the arrow, the action buttons and the flight and instance timers. Shift-drag still moves them."] = "Ok, eylem düğmeleri ve uçuş ve instance zamanlayıcılarındaki istenmeyen sürüklemeleri engeller. Shift ile sürükleyince yine taşınırlar."
L["Line style"] = "Satır stili"
L["Bar at the bottom"] = "Çubuk altta"
L["With Grow upward, put the tabs and the step bar at the bottom edge, next to where the window is pinned."] = "“Yukarı doğru büyü” açıkken sekmeleri ve adım çubuğunu, pencerenin sabitlendiği alt kenara koyar."
L["Close offers the guide skips"] = "Rehberin atladığı teklifleri kapat"
L["After Polestar accepts or turns in a quest, closes the quest window the NPC opens next when the guide skips its quests. Hold Shift to keep it open."] = "Polestar bir görevi aldıktan ya da teslim ettikten sonra, rehber o NPC'nin görevlerini atlıyorsa NPC'nin açtığı sonraki görev penceresini kapatır. Açık tutmak için Shift'e basılı tut."
L["Elite and escort quests the guides mark for a group. Ask at each, or answer them all: with a group (a party levelling together) or skip them (solo). Discovery, Group quests changes one."] = "Rehberlerin grup için işaretlediği elit ve eskort görevleri. Her birinde sor ya da hepsine birden yanıt ver: grupla (birlikte seviye atlayan bir grup) ya da atla (tek başına). Tek birini Keşif, Grup görevleri değiştirir."
L["Ask me at each"] = "Her birinde bana sor"
L["Do them with a group"] = "Grupla yap"
L["Skip them"] = "Atla"
L["Offer class quests"] = "Sınıf görevlerini öner"
L["When one of your class's Class guides opens (your level, its first quest), the guide window offers to open it in a tab."] = "Sınıfının Sınıf rehberlerinden biri açıldığında (seviyen, ilk görevi), rehber penceresi onu bir sekmede açmayı önerir."
L["Celebrating the supporters, contributors and bug reporters behind Polestar."] = "Polestar'ın arkasındaki destekçileri, katkıda bulunanları ve hata bildirenleri anıyoruz."
L["Position trails, marks and the list of spots to walk, in a small window."] = "Konum izleri, işaretler ve yürünecek noktaların listesi, küçük bir pencerede."
L["Reset guide progress?"] = "Rehber ilerlemesi sıfırlansın mı?"
L["Reset progress"] = "İlerlemeyi sıfırla"
L["Reset all settings?"] = "Tüm ayarlar sıfırlansın mı?"
L["Reset all"] = "Tümünü sıfırla"
L["Every Polestar setting goes back to its default. Your guides and progress are kept."] = "Her Polestar ayarı varsayılanına döner. Rehberlerin ve ilerlemen korunur."
L["Preview"] = "Önizleme"
L["Live"] = "Canlı"
-- L["Tirisfal Glades"] = ""
-- L["Garren's Haunt"] = ""
L["Collect Doom Weed"] = "Topla: Doom Weed"
-- L["Rot Hide Mongrel"] = ""
-- L["381 yd"] = ""
-- L["Brill"] = ""
L["Waiting to upload"] = "Yüklenmeyi bekleyen"
L["Chunks the Polestar Uploader has not sent yet."] = "Polestar Uploader'ın henüz göndermediği parçalar."
L["Stored"] = "Saklanan"
L["Last uploaded chunk"] = "Son yüklenen parça"
L["Recordings"] = "Kayıtlar"
L["Chunks waiting, the last upload and the install id, in chat."] = "Bekleyen parçalar, son yükleme ve kurulum kimliği sohbete yazılır."
L["Characters"] = "Karakterler"
L["Map icons"] = "Harita simgeleri"
L["Icon pack"] = "Simge paketi"
L["The medallion under every mark on the world map and the minimap. The skin's: Polestar's, Halo's, or Hearth's for Hearth and the game's own looks. Glyphs only: no medallion."] = "Dünya haritasında ve mini haritada her işaretin altındaki madalyon. Görünümünki: Polestar'ınki, Halo'nunki ya da Hearth ve oyunun kendi görünüşleri için Hearth'ünkü. Yalnızca semboller: madalyon yok."
L["The skin's icons"] = "Görünümün simgeleri"
L["Glyphs only"] = "Yalnızca semboller"
L["Use deathskips"] = "Ölerek kestirme (deathskip) kullan"
L["Where dying on purpose and taking the Spirit Healer's resurrection gets you there sooner, the guide shows a step for it. It costs durability and, from level 11, resurrection sickness. Always off on Hardcore characters."] = "Bilerek ölüp Spirit Healer'dan dirilmek seni oraya daha çabuk götürüyorsa, rehber bunun için bir adım gösterir. Dayanıklılığa mal olur ve 11. seviyeden itibaren resurrection sickness verir. Hardcore karakterlerde her zaman kapalı."
L["Text size"] = "Yazı boyutu"
L["The size of Polestar's text, apart from the window scale. Changes at once. Right-click to reset."] = "Polestar yazılarının boyutu, pencere ölçeğinden ayrı. Hemen değişir. Sıfırlamak için sağ tıkla."
L["Numbered pins for the steps ahead"] = "Sıradaki adımlar için numaralı iğneler"
L["A small pin with its step number where each of the next steps takes you, fainter the further ahead. As many as Up next shows, else five."] = "Sıradaki her adımın seni götürdüğü yerde adım numarasıyla küçük bir iğne; ilerideki daha soluk. Sıradaki'nin gösterdiği kadar, yoksa beş."
L["Class quest chime"] = "Sınıf görevi çınlaması"
L["A short chime the first time a class quest chain's card shows. Off while the game's sound effects are off."] = "Bir sınıf görevi zincirinin kartı ilk kez göründüğünde kısa bir çınlama. Oyunun ses efektleri kapalıyken kapalı."
L["Run"] = "Çalıştır"
L["Reset this page?"] = "Bu sayfa sıfırlansın mı?"
L["Every setting on %s goes back to its default."] = "%s sayfasındaki her ayar varsayılanına döner."
L["When a leveling guide ends"] = "Bir seviye rehberi bittiğinde"
L["Ask me: a window says the guide is done and offers the next one. Continue automatically: the next guide loads in the same tab."] = "Bana sor: bir pencere rehberin bittiğini söyler ve sonrakini önerir. Otomatik devam et: sonraki rehber aynı sekmede açılır."
L["Ask me"] = "Bana sor"
L["Continue automatically"] = "Otomatik devam et"
L["%d KiB"] = "%d KiB"
L["%.1f MB"] = "%.1f MB"
L["%d KB"] = "%d KB"
L["Show the whole step"] = "Adımın tamamını göster"
L["Every goal of the step at once, finished ones kept, instead of one person at a time with the others on one line each."] = "Bir seferde tek kişi ve diğerleri birer satırda yerine, adımın tüm hedefleri bir arada; bitenler de kalır."
L["Maximum height"] = "En fazla yükseklik"
L["How tall the window may grow, as a share of the screen. A longer step scrolls."] = "Pencerenin ekranın ne kadarına kadar uzayabileceği. Daha uzun bir adım kaydırılır."
L["Hide the arrow with the guide"] = "Oku rehberle birlikte gizle"
L["When the guide window is hidden, hide the arrow too."] = "Rehber penceresi gizlenince oku da gizle."
L["Small conveniences: questing, travel, invitations, merchants, bags, trackers and the map."] = "Küçük kolaylıklar: görevler, yolculuk, davetler, satıcılar, çantalar, takipçiler ve harita."
L["Did you mean:"] = "Bunu mu demek istedin:"
L["Minimap icon size"] = "Mini harita simge boyutu"
L["Polestar's marks on the minimap; the world map keeps its own. A mark over your arrow fades so the arrow shows through it. Right-click to reset."] = "Polestar'ın mini haritadaki işaretleri; dünya haritası kendi boyutunu korur. Okunun üstüne gelen bir işaret solar, böylece ok görünür. Sıfırlamak için sağ tıkla."
L["Dungeons and battlegrounds"] = "Zindanlar ve savaş alanları"
L["In dungeons and battlegrounds"] = "Zindanlarda ve savaş alanlarında"
L["How close"] = "Ne kadar yakın"
L["Include nearby hand-ins"] = "Yakındaki teslimleri de ekle"
L["Wait for Spoken"] = "Spoken için bekle"
L["Waits 200 ms before each automatic quest accept, turn-in and reward pick, so Spoken has time to notice the window and read it."] = "Her otomatik görev alma, teslim ve ödül seçiminden önce 200 ms bekler; böylece Spoken pencereyi fark edip okumaya zaman bulur."
L["Dynamic Questing"] = "Dinamik görevler"
L["Sound for a new suggestion"] = "Yeni öneri için ses"
L["Suggests objectives from later steps when you are near them, from your quest log and what is around you. They show under the step in a \"While you're here\" panel: click one to point the arrow there; right-click to dismiss it around here (dismissed twice, it stays away for the zone)."] = "Yakınındayken sonraki adımlardaki hedefleri önerir; görev günlüğüne ve çevrende olanlara bakar. Adımın altında “Hazır buradayken” panelinde görünürler: oku oraya çevirmek için birine tıkla; bu civarda kapatmak için sağ tıkla (iki kez kapatılan, bölge boyunca bir daha gelmez)."
L["A soft chime for each new suggestion (once when several come together), at the game's sound effects volume."] = "Her yeni öneri için yumuşak bir çan sesi (birkaçı bir arada gelince bir kez), oyunun ses efektleri seviyesinde."
L["What's new"] = "Yenilikler"
L["When you abandon a guide quest"] = "Bir rehber görevini bıraktığında"
L["Always go back for it"] = "Her zaman onun için geri dön"
L["Always skip it"] = "Her zaman atla"
L["Ask me: the guide stays on its step, leads you back to the quest giver, and the guide window asks. Or always go back for the quest, or always skip it and the quests that follow from it; chat says which."] = "Bana sor: rehber adımında kalır, seni görevi verene geri götürür ve rehber penceresi sorar. Ya da her zaman görev için geri dön ya da onu ve ondan sonra gelen görevleri her zaman atla; hangisi olduğunu sohbet söyler."
L["Also a quest ready to hand in whose NPC is a little out of your way, when the guide hands it in later."] = "Rehber onu daha sonra teslim ediyorsa, NPC'si yolunun biraz dışında kalan ve teslime hazır bir görev de."
L["Hand-ins: how far out of your way"] = "Teslimler: yolundan ne kadar sapılsın"
L["The seconds of extra walking a hand-in may cost, to its NPC and back on your way. One in the town you are in always shows; 0 keeps to those."] = "Bir teslimin, NPC'sine gidip yoluna dönerken fazladan kaç saniyelik yürüyüşe mal olabileceği. Bulunduğun kasabadaki teslim her zaman görünür; 0 yalnızca onlarla sınırlar."
L["Route line on the minimap"] = "Mini haritada rota çizgisi"
L["The way to the goal on the minimap. Off keeps the guide pin there and the line on the world map. Its colour, opacity and size: the gear beside Guide > Arrow & routes > Route lines."] = "Mini haritada hedefe giden yol. Kapalıyken orada rehber iğnesi, dünya haritasında da çizgi kalır. Rengi, opaklığı ve boyutu: Rehber > Ok ve rotalar > Rota çizgileri yanındaki dişli."
L["Show and hide"] = "Göster ve gizle"
L["Floating button"] = "Yüzen düğme"
L["Step key targets their mobs"] = "Adım tuşu onların yaratıklarını hedef alır"
L["The step key also targets the mobs of the suggestions, nearest first, after the current step's own. It changes only out of combat."] = "Adım tuşu, geçerli adımınkilerden sonra önerilerin yaratıklarını da en yakından başlayarak hedef alır. Yalnızca savaş dışında değişir."
L["Mark quests new in Forever"] = "Forever'da yeni olan görevleri işaretle"
L["A small infinity mark beside the name of a quest Forever added, in the guide, While you're here, the Codex and quest tooltips."] = "Forever'ın eklediği bir görevin adının yanında küçük bir sonsuzluk işareti: rehberde, Hazır buradayken panelinde, Codex'te ve görev ipuçlarında."
L["The way to the goal on the world map and the minimap: a line or dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "Dünya haritasında ve mini haritada hedefe giden yol: yürüdüğün yerde bir çizgi ya da noktalar, uçtuğun, yelken açtığın ya da bindiğin yerde çizgiler; bundan sonraki bacaklar daha soluk. Cillian Berragan'ın Shortest Path Forever'ının çizdiği gibi çizilir."
L["How the route lines are drawn: one solid line, Polestar's dots, or sparkles that drift along the way to the goal (dots while Reduce motion is on)."] = "Rota çizgilerinin nasıl çizileceği: tek bir düz çizgi, Polestar'ın noktaları ya da hedefe giden yol boyunca süzülen ışıltılar (Hareketi azalt açıkken noktalar)."
L["Button in the game menu"] = "Oyun menüsünde düğme"
L["A Polestar button in the game menu (Esc) that opens the guide menu."] = "Oyun menüsünde (Esc) rehber menüsünü açan bir Polestar düğmesi."
L["Backing"] = "Zemin"
L["Soft"] = "Yumuşak"
L["Dark"] = "Koyu"
L["Keep the bar shown"] = "Çubuk hep görünsün"
L["With Transparent, the tabs and the step bar stay on screen instead of only under the cursor."] = "Şeffaf ile sekmeler ve adım çubuğu yalnızca imlecin altındayken değil, sürekli ekranda kalır."
L["With Transparent: Soft lays a light shade behind each line of text, Dark a dark backing behind the whole window. Off: the outlined text alone on the world."] = "Şeffaf ile: Yumuşak her metin satırının arkasına hafif bir gölge koyar, Koyu bütün pencerenin arkasına koyu bir zemin. Kapalı: dünyanın üzerinde yalnızca kenarlıklı metin."
L["Tell me when a newer Polestar is out"] = "Yeni bir Polestar çıkınca bana söyle"
L["At login, a card on the guide window says a newer Polestar is out and how to update; Got it keeps it away for a day. A line in the guide window stays until you update. Two or more updates behind, both show even with this off (the card at most once a day)."] = "Girişte rehber penceresindeki bir kart yeni bir Polestar çıktığını ve nasıl güncelleneceğini söyler; “Anladım” onu bir gün uzak tutar. Rehber penceresindeki bir satır sen güncelleyene dek kalır. İki ya da daha fazla güncelleme gerideysen bu kapalıyken de ikisi görünür (kart en fazla günde bir kez)."
L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. Guide window in the minimap button's menu, the key binding or /polestar opens it there until you leave."] = "Pencerenin, düğmelerinin ve uyarılarının zindanlarda, raidlerde, savaş alanlarında ve arenalarda ne yapacağı. Mini harita düğmesinin menüsündeki “Rehber penceresi”, tuş ataması ya da /polestar, sen çıkana dek pencereyi orada açar."
L["A small Polestar button you can put anywhere on the screen. Click to hide or show Polestar, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Ekranın istediğin yerine koyabileceğin küçük bir Polestar düğmesi. Polestar'ı gizlemek ya da göstermek için tıkla, menü için sağ tıkla, taşımak için sürükle. Savaşta ve zindanlarda, bunlar Gizlensin olarak ayarlıysa pencereyle birlikte gizlenir."
L["Hiding Polestar leaves the arrow, its travel button and its arrival sound. This character only."] = "Polestar'ı gizlemek oku, yolculuk düğmesini ve varış sesini bırakır. Yalnızca bu karakter için."
L["How near the middle of its spawn area you must be for a suggestion to show. It goes again a little further out."] = "Bir önerinin görünmesi için doğma alanının ortasına ne kadar yakın olman gerektiği. Biraz daha uzaklaşınca kaybolur."
L["Flight paths you pass"] = "Yolundaki uçuş noktaları"
L["Also a friendly flight master near you whose flight path you haven't learned yet. Learning it ticks the guide's later step for it too."] = "Yakınında, uçuş noktasını henüz açmadığın dost bir uçuş ustası da. Onu açmak rehberin sonraki adımını da işaretler."
L["Detour captions"] = "Dolanma notları"
L["Under a walk in the journey, say when it goes round a town of the other faction: \"Detour around Southshore\". It only says so: the route and the arrow stay as they are."] = "Yolculuktaki bir yürüyüşün altında, karşı tarafın bir kasabasının çevresinden dolanıyorsa bunu söyler: “Dolanma: Southshore”. Yalnızca söyler: rota ve ok olduğu gibi kalır."
L["Manual check-offs and skips, current guide, from your last quest progress on."] = "Elle işaretlemeler ve atlamalar, geçerli rehber, son görev ilerlemenden bu yana."
L["Your manual check-offs and skipped steps in %s are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "%s içinde son görev ilerlemenden bu yana elle işaretlediklerin ve atladığın adımlar temizlenir. Yaptığın görevler yapılmış kalır, rehber de seni getirdikleri yerde kalır."
L["Your manual check-offs and skipped steps in the current guide are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Geçerli rehberde son görev ilerlemenden bu yana elle işaretlediklerin ve atladığın adımlar temizlenir. Yaptığın görevler yapılmış kalır, rehber de seni getirdikleri yerde kalır."

