L["A guide to the 1 quest here you can take, with what comes before it, ending at the entrance."] = "Buradan alabileceğin 1 görev için, öncesindekilerle birlikte, girişte biten bir rehber."
L["A guide to the %d quests here you can take, with what comes before them, ending at the entrance."] = "Buradan alabileceğin %d görev için, öncesindekilerle birlikte, girişte biten bir rehber."
