L["Nothing to pick up before the run: the quests here for you are done, already in your log, or start inside the dungeon or later in their chain."] = "Koşudan önce alınacak bir şey yok: buradaki görevlerin ya bitti, ya zaten günlüğünde, ya da zindanın içinde veya zincirlerinin ilerisinde başlıyor."
L["1 more opens at a later level."] = "1 tanesi daha ileri bir seviyede açılır."
L["%d more open at a later level."] = "%d tanesi daha ileri bir seviyede açılır."
