L["Type a name: a mount, an item, a pet, an NPC, a quest, a dungeon or a zone. Select a result to see where to get it, best for you first."] = "Bir ad yaz: binek, eşya, evcil hayvan, NPC, görev, zindan ya da bölge. Nereden alınacağını görmek için bir sonuç seç; sana en uygunu başta."
