L["Lookup is turned off in Options > Discovery > Lookup, so items, mounts, NPCs and quests are not searched."] = "Arama, Seçenekler > Keşif > Arama'da kapalı; bu yüzden eşyalar, binekler, NPC'ler ve görevler aranmıyor."
L["Items, mounts, NPCs and quests are searched once the Codex loads."] = "Codex yüklenince eşyalar, binekler, NPC'ler ve görevler de aranır."
