-- QoL/Options.lua
L["Off by default: %s does this too."] = "Varsayılan olarak kapalı: %s de bunu yapıyor."
L["Quest item button"] = "Görev eşyası düğmesi"
L["Highlight the step's item in your bags"] = "Adımın eşyasını çantanda vurgula"
L["Polestar: step item"] = "Polestar: adım eşyası"
L["A button for the current step's quest item, with count, cooldown and range. Bind it under Key Bindings > AddOns."] = "Geçerli adımın görev eşyası için sayısı, bekleme süresi ve menzili olan bir düğme. Key Bindings > AddOns altında tuş ata."
L["Target button"] = "Hedef düğmesi"
L["Targets the current step's mobs by name, or the NPCs it sends you to when it has no mob; each click moves to the next name. Bindable."] = "Geçerli adımın yaratıklarını ya da yaratık yoksa seni gönderdiği NPC'leri adıyla hedef alır; her tıklama sonraki ada geçer. Tuş atanabilir."
L["Show who it targets"] = "Kimi hedef aldığını göster"
L["The target button's icon shows what you do next: talk, accept, turn in, kill or loot, a skull for an elite, rare or boss, or their face once you have seen them. Their name sits beside it, green for a friendly NPC, red for a mob, gold for an elite or rare, with small icons for the names after it."] = "Hedef düğmesinin simgesi sırada ne yapacağını gösterir: konuş, görevi al, teslim et, öldür ya da loot'la; elit, rare ya da boss için kafatası, onları bir kez gördüysen de yüzleri. Adları yanında durur: dost NPC için yeşil, yaratık için kırmızı, elit ya da rare için altın; sonraki adlar için küçük simgelerle."
L["Name new targets in chat"] = "Yeni hedefleri sohbette yaz"
L["When the target button's names change, one line in chat lists them (\"Targeting: ...\"). Only you see it."] = "Hedef düğmesinin adları değişince sohbette tek bir satır onları listeler (\"Hedefleniyor: ...\"). Yalnızca sen görürsün."
L["Targeting: %s"] = "Hedefleniyor: %s"
L["Hearthstone button"] = "Hearthstone düğmesi"
L["Shows your Hearthstone while the guide says to hearth. Bindable."] = "Rehber Hearthstone kullanmanı söylerken Hearthstone'unu gösterir. Tuş atanabilir."
L["Button size"] = "Düğme boyutu"
L["Target name position"] = "Hedef adının konumu"
L["Where the target's name shows around the target button: right, left, above or below."] = "Hedefin adının hedef düğmesinin neresinde görüneceği: sağda, solda, üstte ya da altta."
L["Right"] = "Sağ"
L["Left"] = "Sol"
L["Above"] = "Üst"
L["Below"] = "Alt"
L["Reset button positions"] = "Düğme konumlarını sıfırla"
L["Put the buttons back in their default spot."] = "Düğmeleri varsayılan yerlerine geri koyar."
L["Mark quest rewards"] = "Görev ödüllerini işaretle"
L["Take the best reward"] = "En iyi ödülü al"
L["Chooses that reward for you when you complete the quest. Hold Shift to choose yourself."] = "Görevi tamamladığında o ödülü senin için seçer. Kendin seçmek için Shift'e basılı tut."
L["Instant quest text"] = "Anında görev metni"
L["Shows quest text at once instead of fading it in (Forever's own option)."] = "Görev metnini yavaşça belirtmek yerine hemen gösterir (Forever'ın kendi seçeneği)."
L["Skip single-option gossip"] = "Tek seçenekli konuşmaları atla"
L["Faster auto-loot"] = "Daha hızlı otomatik loot"
L["Takes the whole corpse at once when auto-loot is on."] = "Otomatik loot açıkken cesetteki her şeyi bir seferde alır."
L["Hide combat errors"] = "Savaş hatalarını gizle"
L["Hides \"Not enough rage\", \"Out of range\" and cooldown messages. Other errors still show."] = "\"Not enough rage\", \"Out of range\" ve bekleme süresi mesajlarını gizler. Diğer hatalar yine görünür."
L["Open the flight map"] = "Uçuş haritasını aç"
L["Talking to a flight master opens the map directly. Hold Shift for the gossip."] = "Uçuş ustasıyla konuşunca harita doğrudan açılır. Konuşma metni için Shift'e basılı tut."
L["Mark the route's destination"] = "Rotanın varış yerini işaretle"
L["Marks where the travel route flies next on the flight map. You still choose the flight."] = "Yolculuk rotasının sonra nereye uçacağını uçuş haritasında işaretler. Uçuşu yine sen seçersin."
L["Corpse or Spirit Healer"] = "Ceset ya da Spirit Healer"
L["As a ghost, points the arrow at the faster way back: your corpse or the nearest Spirit Healer."] = "Hayaletken oku daha hızlı dönüş yoluna çevirir: cesedine ya da en yakın Spirit Healer'a."
L["Release in battlegrounds"] = "Savaş alanlarında ruhu bırak"
L["Releases your spirit at once when you die in a battleground, unless you can resurrect yourself or someone offers to. Hold Shift to stay."] = "Bir savaş alanında ölünce, kendini diriltemiyorsan ya da biri teklif etmiyorsa ruhunu hemen bırakır. Kalmak için Shift'e basılı tut."
L["Accept summons"] = "Çağrıları kabul et"
L["Takes a summon at once, unless you are in combat. Hold Shift to decide yourself."] = "Savaşta değilsen çağrıyı hemen kabul eder. Kendin karar vermek için Shift'e basılı tut."
L["Accept resurrections"] = "Diriltmeleri kabul et"
L["Takes a resurrection as soon as it can, unless the caster is in combat. Never in Hardcore. Hold Shift to decide yourself."] = "Dirilten kişi savaşta değilse diriltmeyi ilk fırsatta kabul eder. Hardcore'da asla. Kendin karar vermek için Shift'e basılı tut."
L["Join friends' parties"] = "Arkadaşların gruplarına katıl"
L["Accepts party invitations from friends, Battle.net friends and your guild, unless joining would leave a queue. Hold Shift to decide yourself."] = "Katılmak bir sıradan çıkarmayacaksa arkadaşlarından, Battle.net arkadaşlarından ve loncandan gelen grup davetlerini kabul eder. Kendin karar vermek için Shift'e basılı tut."
L["Decline other party invitations"] = "Diğer grup davetlerini reddet"
L["Declines party invitations from anyone who is not a friend or in your guild."] = "Arkadaşın ya da loncanda olmayan herkesin grup davetini reddeder."
L["Decline guild invitations"] = "Lonca davetlerini reddet"
L["Declines guild invitations, except from friends."] = "Arkadaşlarından gelenler dışındaki lonca davetlerini reddeder."
L["Decline duels"] = "Düelloları reddet"
L["Declines duel requests, except from friends and your guild."] = "Arkadaşların ve loncan dışındaki düello isteklerini reddeder."
L["Sell grey items"] = "Gri eşyaları sat"
L["Repair"] = "Onar"
L["Repairs all gear at merchants who can, when you can afford it. Hold Shift to skip."] = "Paran yetiyorsa tamir yapabilen satıcılarda tüm ekipmanı onarır. Atlamak için Shift'e basılı tut."
L["Guild bank first"] = "Önce lonca bankası"
L["When your guild rank may, the guild bank pays for repairs and your money covers the rest."] = "Lonca rütben izin veriyorsa onarımı lonca bankası öder, kalanını senin paran karşılar."
L["XP tracker"] = "XP takipçisi"
L["XP per hour, time, kills and quests to level, and level splits (/pole xp)."] = "Saatlik XP; seviye atlamak için süre, öldürme ve görev sayısı; seviye süreleri (/pole xp)."
L["Reset session"] = "Oturumu sıfırla"
L["Start this session's XP per hour from zero."] = "Bu oturumun saatlik XP'sini sıfırdan başlatır."
L["Mark what they target"] = "Hedef aldıklarını işaretle"
L["A new one each press"] = "Her basışta yenisi"
L["Icon on mobs"] = "Yaratıklarda simge"
L["A new one each press skips the NPCs' icon and leaves a mob that has one as it is."] = "“Her basışta yenisi”, NPC'lerin simgesini atlar ve zaten simgesi olan bir yaratığa dokunmaz."
L["Icon on NPCs"] = "NPC'lerde simge"
L["A new one each press, so the last few NPCs keep theirs. Every press counts, even one that marks nothing."] = "Her basışta yenisi; böylece son birkaç NPC simgesini korur. Hiçbir şeyi işaretlemeyen basış da sayılır."
L["Rare button"] = "Rare düğmesi"
L["Shows a button that targets a rare Polestar spotted nearby, until it dies or is out of sight. Bindable."] = "Polestar'ın yakında gördüğü bir rare'i, ölene ya da gözden kaybolana dek hedef alan bir düğme gösterir. Tuş atanabilir."
L["Scale of the quest item, Hearthstone, target and rare buttons. Drag one to move them all."] = "Görev eşyası, Hearthstone, hedef ve rare düğmelerinin ölçeği. Hepsini taşımak için birini sürükle."
L["Guide level on the XP bar"] = "XP çubuğunda rehber seviyesi"
L["A mark at the end of the game's XP bar with the level the guide wants you to reach before it moves on, and how many levels away that is when it is more than one."] = "Oyunun XP çubuğunun ucunda, rehberin devam etmeden önce ulaşmanı istediği seviyeyi ve birden fazlaysa kaç seviye uzakta olduğunu gösteren bir işaret."
-- L["Hearthstone"] = ""
L["Set your home at the guide's inn"] = "Hearthstone'u rehberin hanına bağla"
L["When the step sets your home and you talk to its innkeeper, binds your Hearthstone there. Never at another inn. Hold Shift to skip."] = "Adım Hearthstone bağlamanı istiyorsa ve o hancıyla konuşursan Hearthstone'unu oraya bağlar. Başka bir handa asla. Atlamak için Shift'e basılı tut."
L["Riding reminder"] = "Binicilik hatırlatıcısı"
L["At level 40 and 60, if you have not learned riding yet, says the cost in chat (with any Honored discount) and points the arrow at your race's riding trainer when you can afford it. Warlocks and Alliance Paladins are sent to their free-mount quest NPC instead. Once per tier per character."] = "Seviye 40 ve 60'ta binmeyi henüz öğrenmediysen maliyeti sohbete yazar (varsa Honored indirimiyle) ve paran yettiğinde oku ırkının binicilik eğitmenine çevirir. Warlock'lar ve Alliance Paladin'leri bunun yerine bedava binek görevini veren NPC'ye gönderilir. Her karakter için her kademede bir kez."
L["Hide the game's quest tracker"] = "Oyunun görev izleyicisini gizle"
L["Hides the game's tracker on the right of the screen, with its quests, achievements and professions, as Questie can. Not with the gamepad interface."] = "Ekranın sağındaki oyun izleyicisini görevleri, başarımları ve meslekleriyle birlikte gizler, Questie'nin yapabildiği gibi. Oyun kumandası arayüzüyle olmaz."
L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator). An item a later step needs gets a lock, so you don't sell it."] = "Geçerli adımın kullandığı eşya ya da topladığı görev eşyası çantanda (ve Baganator'da) parlar. Sonraki bir adımın gerektirdiği eşyaya kilit konur, böylece onu satmazsın."
L["Loot and merchants"] = "Loot ve satıcılar"
L["Offer gear upgrades"] = "Ekipman iyileştirmelerini öner"
L["When gear from a kill, a chest or a merchant is an upgrade for your spec (with Gear advice on), the guide window offers to put it on. Nothing goes on until you press Wear it; Not this one stops it asking about that item."] = "Bir öldürmeden, bir sandıktan ya da bir satıcıdan gelen ekipman uzmanlığın için bir iyileştirmeyse (Ekipman önerisi açıkken), rehber penceresi onu giymeyi önerir. Giy'e basana kadar hiçbir şey giyilmez; Bunu değil, o eşya için sormayı bırakır."
L["Sells Poor-quality items, and anything you marked as junk, when a merchant opens and prints the total. Never an item marked to keep or one a later step needs."] = "Satıcı açılınca Poor kalitesindeki eşyaları ve çöp olarak işaretlediğin her şeyi satar, toplamı yazar. Saklanacak olarak işaretlenmiş ya da sonraki bir adımın gerektirdiği eşyayı asla satmaz."
L["Restock button"] = "Stok tamamla düğmesi"
L["At a merchant that sells what you are short of, a Restock button under its window buys up to the amounts below (this character's). Nothing is bought until you press it. Other items, such as reagents: /polestar restock <item> <amount>."] = "Eksiğin olanı satan bir satıcıda, penceresinin altındaki Stok tamamla düğmesi aşağıdaki miktarlara kadar satın alır (bu karakterinkiler). Basana kadar hiçbir şey alınmaz. Reagent gibi başka eşyalar için: /polestar restock <item> <amount>."
L["Keeps this many drinks in your bags. The merchant's best one for your level is bought."] = "Çantanda bu kadar içecek tutar. Satıcının seviyene göre en iyisi alınır."
L["Keeps this much food in your bags. The merchant's best one for your level is bought."] = "Çantanda bu kadar yiyecek tutar. Satıcının seviyene göre en iyisi alınır."
L["Keeps this many arrows or shot for the bow, crossbow or gun you wear."] = "Taktığın yay, arbalet ya da tüfek için bu kadar ok ya da mermi tutar."
L["Bags"] = "Çantalar"
L["When your bags are nearly full, a button shows the free slots and the cheapest junk in them, and while the step collects something the guide window says so too. Press twice to delete that junk: grey items, or common ones you marked as junk. Bindable."] = "Çantaların neredeyse dolunca bir düğme boş yuvaları ve içlerindeki en ucuz çöpü gösterir; adım bir şey toplarken rehber penceresi de bunu söyler. O çöpü silmek için iki kez bas: gri eşyalar ya da çöp olarak işaretlediğin sıradan eşyalar. Tuş atanabilir."
L["Nearly full at"] = "Neredeyse dolu sınırı"
L["%d slot"] = "%d yuva"
L["%d slots"] = "%d yuva"
L["How many free slots or fewer count as nearly full."] = "Kaç ya da daha az boş yuvanın neredeyse dolu sayılacağı."
L["Junk and keep marks"] = "Çöp ve saklama işaretleri"
L["Ctrl+Alt-click an item in your bags to mark it as junk, again to keep it, and again to clear it. Junk is sold with the grey items; a kept item is never sold or deleted."] = "Çantandaki bir eşyaya Ctrl+Alt ile tıkla: ilk tık çöp olarak işaretler, ikincisi saklanacak yapar, üçüncüsü işareti kaldırır. Çöp gri eşyalarla birlikte satılır; saklanan eşya asla satılmaz ya da silinmez."
L["Step key talks and loots"] = "Adım tuşu konuşur ve loot'lar"
L["Once the step key has targeted the step's NPC, the next press talks to it; on the corpse of the step's mob, it loots; in the step's quest window, it accepts or completes. Only out of combat, and only on the step the guide is at."] = "Adım tuşu adımın NPC'sini hedef aldıktan sonra sonraki basış onunla konuşur; adımın yaratığının cesedinde loot'lar; adımın görev penceresinde görevi alır ya da tamamlar. Yalnızca savaş dışında ve yalnızca rehberin bulunduğu adımda."
L["Warn when out of breath"] = "Nefesin bitince uyar"
L["Under water, a red edge round the screen, a sound and a taskbar flash with 10 seconds of breath left, and again at 4."] = "Su altında 10 saniyelik nefesin kaldığında ekranın çevresinde kırmızı bir kenar, bir ses ve görev çubuğunda yanıp sönme; 4 saniyede yeniden."
L["Pick what the step asks for"] = "Adımın istediğini seç"
L["At the step's NPC, picks the chat option the guide names, or opens the goods or training the step needs. Only on the step the guide is at. Hold Shift to choose yourself."] = "Adımın NPC'sinde rehberin adını verdiği konuşma seçeneğini seçer ya da adımın gerektirdiği malları veya eğitimi açar. Yalnızca rehberin bulunduğu adımda. Kendin seçmek için Shift'e basılı tut."
L["Picks the only option of NPCs without quests. Hold Shift to read it. Off, the game still skips some itself, Pick what the step asks for still picks the step's option, and flight masters follow Open the flight map."] = "Görevi olmayan NPC'lerin tek seçeneğini seçer. Okumak için Shift'e basılı tut. Kapalıyken oyun yine bazılarını kendisi geçer, Adımın istediğini seç yine adımın seçeneğini seçer ve uçuş ustaları Uçuş haritasını aç ayarına uyar."
L["Reset"] = "Sıfırla"
L["Click objectives to target"] = "Hedef satırına tıklayınca NPC'yi hedef al"
L["Clicking an objective row or NPC heading also targets its NPC outside combat, using the same marking settings as the Target button. This replaces your current target; a failed search clears it."] = "Bir hedef satırına ya da NPC başlığına tıklamak, savaş dışında onun NPC'sini de hedef alır; “Hedef” düğmesiyle aynı işaretleme ayarlarını kullanır. Bu, geçerli hedefinin yerini alır; bulamayan bir arama hedefini temizler."
L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Pressing again never takes an icon off. In a party you don't lead, only a unit with no icon gets one; in a raid, only when you lead or assist."] = "Hedef düğmesi ve adım tuşu, hedef aldıkları yaratığa ve NPC'ye bir raid simgesi koyar; savaş dışında ikisini de bulamayan bir basış hedefini temizler. Yeniden basmak bir simgeyi asla kaldırmaz. Lideri olmadığın bir grupta yalnızca simgesi olmayan bir birim simge alır; raidde ise yalnızca lider ya da yardımcıysan."
L["Ping what they target"] = "Hedef aldıklarına ping at"
L["The target button and the step key ping the mob they target, so your group sees it behind rocks and buildings. Never in a raid unless you lead or assist. The rare buttons always ping."] = "Hedef düğmesi ve adım tuşu hedef aldıkları yaratığa ping atar; böylece grubun onu kayaların ve binaların arkasında da görür. Lider ya da yardımcı değilsen raidde asla. Rare düğmeleri her zaman ping atar."
L["Show quest-starting loot"] = "Görev başlatan loot'u göster"
L["When you loot an item that starts a quest you can take, it goes on the quest item button with a glow until you click it or take the quest. The step's own item comes first; several wait their turn, oldest first."] = "Alabileceğin bir görevi başlatan bir eşyayı loot'layınca, sen ona tıklayana ya da görevi alana dek parlayarak görev eşyası düğmesine geçer. Adımın kendi eşyası önce gelir; birkaç tane varsa en eskisinden başlayarak sırayla bekler."
L["Track only dungeon quests in dungeons"] = "Zindanlarda yalnızca zindan görevlerini izle"
L["Inside a dungeon or raid, the game's quest tracker and Polestar's quest markers show only that instance's quests. The quests you were tracking come back when you leave, even after a reload inside."] = "Bir zindanda ya da raidde oyunun görev izleyicisi ve Polestar'ın görev işaretleri yalnızca o instance'ın görevlerini gösterir. İzlediğin görevler sen çıkınca geri gelir, içeride yeniden yüklesen bile."
L["New spells at level-up"] = "Seviye atlayınca yeni büyüler"
L["When you level up, a card on the guide window shows the class spells you can now train, what they cost together and the nearest class trainer, with a button for the arrow. Not in combat or instances, and not on levels with nothing new."] = "Seviye atlayınca rehber penceresindeki bir kart artık öğrenebileceğin sınıf büyülerini, toplam ücretlerini ve en yakın sınıf eğitmenini, ok için bir düğmeyle gösterir. Savaşta, instance'larda ve yeni bir şey getirmeyen seviyelerde gösterilmez."
L["Old ranks on your bars"] = "Çubuklarındaki eski rank'lar"
L["After training and at login, says which spells on your action bars are a lower rank than the one in your spellbook, with a button that puts the highest rank in the same buttons (out of combat). Macros and items are never touched. Right-click a spell on the card to keep it at its rank; a lower rank you put on a bar yourself is kept too."] = "Eğitimden sonra ve girişte, eylem çubuklarındaki hangi büyülerin büyü kitabındakinden düşük rank olduğunu söyler; en yüksek rank'ı aynı düğmelere koyan bir düğmeyle birlikte (savaş dışında). Makrolara ve eşyalara asla dokunulmaz. Bir büyüyü kendi rank'ında tutmak için karttaki büyüye sağ tıkla; bir çubuğa kendin koyduğun düşük rank da korunur."
L["Forget kept ranks"] = "Korunan rank'ları unut"
L["Lists the spells you kept at a lower rank again."] = "Düşük rank'ta tuttuğun büyüleri yeniden listeler."
L["Boosted Rest status"] = "Boosted Rest durumu"
L["How long the campfire's Boosted Rest lasts and the Cozy Sleeping Bag's cooldown, under the guide window's XP line; your party's Boosted Rest in the party panel."] = "Kamp ateşinin Boosted Rest'inin ne kadar sürdüğü ve Cozy Sleeping Bag'in bekleme süresi, rehber penceresinin XP satırının altında; grubunun Boosted Rest'i grup panelinde."
L["Take the marked flight"] = "İşaretli uçuşa bin"
L["When the flight map opens, flies to the marked destination. Hold Shift at the flight master to choose yourself."] = "Uçuş haritası açılınca işaretli hedefe uçar. Kendin seçmek için uçuş ustasının yanında Shift'e basılı tut."

-- Rares/View.lua, Rares/Options.lua
