L["%d zones"] = "%d bölge"
L["Rare NPCs and treasures, what they drop and where they spawn"] = "Rare NPC'ler ve hazineler, ne düşürdükleri ve nerede doğdukları"
L["Rares is turned off."] = "Rare'ler kapalı."
L["Nothing to list without the Codex."] = "Codex olmadan listelenecek bir şey yok."
