L["Watch for rare NPCs and treasures and keep when you last met them (/pole rares). Their map pins are under Map, off by default."] = "Rare NPC'leri ve hazineleri izler, onlarla en son ne zaman karşılaştığını saklar (/pole rares). Harita iğneleri Harita altında, varsayılan olarak kapalı."
L["Alert for rares"] = "Rare uyarısı"
L["A card with its name, level and distance, and a waypoint to it."] = "Adı, seviyesi ve mesafesiyle bir kart ve ona giden bir yol noktası."
L["Alert for treasures"] = "Hazine uyarısı"
L["Treasures the client marks on the minimap."] = "Oyunun mini haritada işaretlediği hazineler."
L["Once per rare every"] = "Rare başına en fazla"
L["The same rare stays quiet this long after an alert."] = "Aynı rare bir uyarıdan sonra bu süre boyunca sessiz kalır."
L["Alert stays for"] = "Uyarı ekranda kalma süresi"
L["Hovering the alert holds it."] = "Fareyle üstüne gelince uyarı ekranda kalır."
