L["Minimap markers"] = "Mini harita işaretleri"
L["Rares and treasures the client marks on the minimap (vignettes), with their exact distance."] = "Oyunun mini haritada işaretlediği rare'ler ve hazineler (vignette), tam mesafeleriyle."
L["Nameplates"] = "İsim plakaları"
L["A rare's nameplate coming into view. Needs enemy nameplates on."] = "Bir rare'in isim plakasının görünmesi. Düşman isim plakalarının açık olması gerekir."
L["Your target"] = "Hedefin"
L["Targeting a rare."] = "Bir rare'i hedef almak."
L["Under the cursor"] = "İmlecin altında"
L["Pointing at a rare in the world."] = "Dünyada bir rare'in üstüne gelmek."
L["Rares on the world map"] = "Dünya haritasında rare'ler"
L["Every known spawn point. Click one to see it in Rares; Shift-click for a waypoint."] = "Bilinen her doğma noktası. Rare'ler sayfasında görmek için tıkla; yol noktası için Shift+tık."
L["Treasures on the world map"] = "Dünya haritasında hazineler"
L["Every known treasure spot."] = "Bilinen her hazine noktası."
L["Rares on the minimap"] = "Mini haritada rare'ler"
L["Loads the Codex at login."] = "Codex'i girişte yükler."
L["Treasures on the minimap"] = "Mini haritada hazineler"
L["Hide rares below your level"] = "Seviyenin altındaki rare'leri gizle"
L["Rares too low to give experience leave the map."] = "Tecrübe vermeyecek kadar düşük rare'ler haritadan kalkar."
L["Forget rares met on this realm"] = "Bu realm'de karşılaşılan rare'leri unut"
L["Clears the Seen list, alert cooldowns and the glow on recently seen pins."] = "Görülenler listesini, uyarı bekleme sürelerini ve yakın zamanda görülen iğnelerdeki parıltıyı temizler."
L["Say when Polestar's founder is nearby"] = "Polestar'ın kurucusu yakındaysa söyle"
L["When %s comes into sight, a card says so and the rare button targets him and waves. At most once a day, never in combat or instances."] = "%s görüş alanına girince bir kart bunu söyler, rare düğmesi de onu hedef alıp el sallar. En fazla günde bir kez; savaşta ya da instance'larda asla."

-- Maps/Maps.lua
L["Dungeon entrances"] = "Zindan girişleri"
L["Marks each dungeon entrance with its level range. Click to open the dungeon's guide, or to set a waypoint when there is none; Shift-click always sets a waypoint. Needs the Codex pack."] = "Her zindan girişini seviye aralığıyla işaretler. Zindanın rehberini açmak için tıkla, rehberi yoksa yol noktası koyar; Shift+tık her zaman yol noktası koyar. Codex paketi gerekir."
L["Your faction's and neutral flight masters: green when known, amber when not yet discovered. The tooltip lists destinations and flight times."] = "Tarafının ve tarafsız uçuş ustaları: biliniyorsa yeşil, henüz keşfedilmediyse kehribar. İpucu varış yerlerini ve uçuş sürelerini listeler."
L["Boats and zeppelins"] = "Gemiler ve zeplinler"
L["Docks, zeppelin towers and the Deeprun Tram, with where they go."] = "İskeleler, zeplin kuleleri ve Deeprun Tram, nereye gittikleriyle."
L["Inns"] = "Hanlar"
L["Innkeepers; the one your Hearthstone is bound to is marked."] = "Hancılar; Hearthstone'unun bağlı olduğu işaretlidir."
L["Travel icons on the minimap"] = "Mini haritada yolculuk simgeleri"
L["Shows the flight masters, docks and inns turned on here on the minimap as well."] = "Burada açık olan uçuş ustalarını, iskeleleri ve hanları mini haritada da gösterir."
L["Unexplored areas"] = "Keşfedilmemiş alanlar"
L["Shows the parts of each zone you have not explored yet, so the whole map is there before you visit. Tinted keeps them apart from where you have been."] = "Her bölgenin henüz keşfetmediğin kısımlarını gösterir; böylece gitmeden önce haritanın tamamı görünür. Renkli seçenek onları gittiğin yerlerden ayırır."
L["Hidden"] = "Gizli"
L["Revealed"] = "Açık"
L["Revealed and tinted"] = "Açık ve renkli"
L["Zone level ranges"] = "Bölge seviye aralıkları"
L["Shows each zone's level range on the continent and zone maps, coloured by difficulty for your level."] = "Kıta ve bölge haritalarında her bölgenin seviye aralığını, seviyene göre zorluk rengiyle gösterir."
L["Shows your position and the cursor's position under the world map."] = "Dünya haritasının altında senin ve imlecin konumunu gösterir."
L["Coordinates on the minimap"] = "Mini haritada koordinatlar"
L["A small readout of your position at the bottom of the minimap."] = "Mini haritanın altında konumunu gösteren küçük bir gösterge."
L["While flying, shows the destination and the time left. Learns each route's real duration for this character; drag to move."] = "Uçarken varış yerini ve kalan süreyi gösterir. Her rotanın gerçek süresini bu karakter için öğrenir; taşımak için sürükle."
L["Forget learned flight times"] = "Öğrenilen uçuş sürelerini unut"
L["Clears this character's recorded flight durations; estimates are used until they are flown again."] = "Bu karakterin kaydedilmiş uçuş sürelerini temizler; yeniden uçulana dek tahminler kullanılır."
L["Learned flight times cleared."] = "Öğrenilen uçuş süreleri temizlendi."
L["Track instances"] = "Instance'ları takip et"
L["Records dungeon and raid entries, time and experience per run. /pole instances lists them."] = "Zindan ve raid girişlerini, her koşunun süresini ve tecrübesini kaydeder. /pole instances listeler."
L["Compact display"] = "Kompakt gösterim"
L["Shows the hourly instance count and the current run while it matters; drag to move."] = "Önemli olduğu sürece saatlik instance sayısını ve geçerli koşuyu gösterir; taşımak için sürükle."
L["Instances per hour"] = "Saatlik instance"
L["Classic allows 5 new instances per hour per account. Forever may differ; adjust if it does."] = "Classic, hesap başına saatte 5 yeni instance'a izin verir. Forever'da farklı olabilir; öyleyse ayarla."
L["Instances per day"] = "Günlük instance"
L["Classic Era allows 30 new instances per 24 hours per account; 0 ignores the daily cap. Forever may differ."] = "Classic Era, hesap başına 24 saatte 30 yeni instance'a izin verir; 0 günlük sınırı yok sayar. Forever'da farklı olabilir."
L["Clear instance history"] = "Instance geçmişini temizle"
L["Forgets recorded entries and runs (the server's own limit is not affected)."] = "Kaydedilen girişleri ve koşuları unutur (sunucunun kendi sınırı etkilenmez)."
L["Minimap button"] = "Mini harita düğmesi"
L["Forget"] = "Unut"
L["Clear"] = "Temizle"
L["Minimap"] = "Mini harita"
L["A Polestar button on the edge of the minimap. Click to hide or show Polestar, right-click for a menu, drag to move it."] = "Mini haritanın kenarında bir Polestar düğmesi. Polestar'ı gizlemek ya da göstermek için tıkla, menü için sağ tıkla, taşımak için sürükle."

-- Quests/Options.lua
L["Any level"] = "Her seviye"
L["Quest, NPC and item data for markers and tooltips, loaded when one of them is on (about 5 MB of memory)."] = "İşaretler ve ipuçları için görev, NPC ve eşya verileri; bunlardan biri açıkken yüklenir (yaklaşık 5 MB bellek)."
L["Available quests"] = "Alınabilir görevler"
L["Mark quest givers with quests you can accept now."] = "Şu an alabileceğin görevleri olan görev verenleri işaretle."
L["Quests above your level"] = "Seviyenin üstündeki görevler"
L["Mark quests up to this many levels above yours."] = "Seviyenin bu kadar üstüne kadarki görevleri işaretle."
L["Low-level quests"] = "Düşük seviyeli görevler"
L["Also mark grey quests that are far below your level."] = "Seviyenin çok altındaki gri görevleri de işaretle."
L["World map objectives"] = "Dünya haritasında hedefler"
L["Mark mob areas, item sources and objects for quests in your log."] = "Günlüğündeki görevler için yaratık alanlarını, eşya kaynaklarını ve nesneleri işaretle."
L["Turn-ins"] = "Teslimler"
L["Mark who to return to once a quest is ready."] = "Görev hazır olunca kime döneceğini işaretle."
L["Show the same quest markers on the minimap."] = "Aynı görev işaretlerini mini haritada da göster."
L["Highlight step quests"] = "Adımın görevlerini vurgula"
L["Enlarge and light up the markers of the quests in your guide's current step."] = "Rehberinin geçerli adımındaki görevlerin işaretlerini büyüt ve parlat."
L["Dim other quests"] = "Diğer görevleri soluklaştır"
L["While a guide runs, fade every quest marker that is not part of its current step."] = "Bir rehber çalışırken geçerli adımına ait olmayan her görev işaretini soluklaştır."
L["Quest tooltips"] = "Görev ipuçları"
L["Name the quests a mob, item or object is for, with your progress."] = "Bir yaratığın, eşyanın ya da nesnenin hangi görevler için olduğunu ilerlemenle birlikte göster."
L["Nameplate icons"] = "İsim plakası simgeleri"
L["Show a quest icon and your progress, like 3/10, on nameplates of mobs you still need."] = "Hâlâ ihtiyacın olan yaratıkların isim plakalarında bir görev simgesi ve 3/10 gibi ilerlemeni göster."
L["Quest levels"] = "Görev seviyeleri"
L["Show quest levels, like [12], wherever the game lists quests without them."] = "Oyunun görevleri seviyesiz listelediği her yerde [12] gibi görev seviyelerini göster."
L["Quest database is off."] = "Görev veritabanı kapalı."
L["Quest database not installed (Polestar_QuestDB)."] = "Görev veritabanı yüklü değil (Polestar_QuestDB)."
L["quests"] = "görev"
L["available now"] = "şu an alınabilir"
L["mobs tracked"] = "takip edilen yaratık"
L["Quest database status"] = "Görev veritabanı durumu"
L["Quest marks in bags"] = "Çantalarda görev işaretleri"
L["Mark bag items a quest still needs, in your log or ahead in your guide, until you hand the quest in."] = "Bir görevin hâlâ ihtiyaç duyduğu çanta eşyalarını, görev günlüğünde ya da rehberde ileride olsun, görevi teslim edene kadar işaretle."
L["Offer to buy back quest items"] = "Görev eşyalarını geri satın almayı öner"
L["If you sell an item a quest still needs, ask whether to buy it back from the vendor."] = "Bir görevin hâlâ ihtiyaç duyduğu bir eşyayı satarsan, onu satıcıdan geri satın almak isteyip istemediğini sor."
L["Nameplate icon position"] = "İsim plakası simgesinin konumu"
L["Where the quest icon and your progress sit on a nameplate: left or right of the health bar, or above the name. Move them if another addon's icon covers them."] = "Görev simgesinin ve ilerlemenin isim plakasında nerede duracağı: can çubuğunun solunda, sağında ya da adın üstünde. Başka bir eklentinin simgesi onları örtüyorsa taşı."
L["Objective spots on the map"] = "Haritada hedef noktaları"
L["A goal's spots close together can draw as one shaded area with one marker in the middle, so the map stays readable."] = "Bir hedefin birbirine yakın noktaları, ortasında tek işaret olan tek bir gölgeli alan olarak çizilebilir; böylece harita okunur kalır."
L["Areas for groups"] = "Gruplar için alanlar"
L["Icons only"] = "Yalnızca simgeler"
L["Areas only"] = "Yalnızca alanlar"
L["Area opacity"] = "Alan opaklığı"
L["How strongly the objective areas tint the map."] = "Hedef alanlarının haritayı ne kadar güçlü renklendireceği."
L["Quest marker size"] = "Görev işareti boyutu"
L["The size of every quest marker on the world map and the minimap."] = "Dünya haritasında ve mini haritada her görev işaretinin boyutu."
L["Timed quest alerts"] = "Süreli görev uyarıları"
L["A chat line and a sound when a timed quest has 5 minutes left, again at 1 minute, and if it fails. The guide window always shows the time left."] = "Süreli bir görevin 5 dakikası kalınca, 1 dakika kalınca yine ve başarısız olursa sohbette bir satır ve bir ses. Rehber penceresi kalan süreyi her zaman gösterir."

-- UI/Packs.lua (the pack report lines stay English: authors read them)
L["turned off in the AddOns list"] = "AddOns listesinde kapalı"
