L["No community addons installed."] = "Yüklü topluluk eklentisi yok."
L["Suggestions"] = "Öneriler"
L["Suggest guides from"] = "Rehber önerilerinin kaynağı"
L["Where the guide for your level is suggested from. Polestar's guides fill in where a community addon has none for you."] = "Seviyene uygun rehberin nereden önerileceği. Bir topluluk eklentisinde sana uygun rehber yoksa Polestar'ın rehberleri devreye girer."
L["About community guides"] = "Topluluk rehberleri hakkında"
L["A community addon is a separate addon with someone else's guides for Polestar. It is not part of Polestar, and its guides are not Polestar's own routes."] = "Topluluk eklentisi, Polestar için başka birinin rehberlerini içeren ayrı bir eklentidir. Polestar'ın parçası değildir ve rehberleri Polestar'ın kendi rotaları değildir."
L["Get a community addon from wherever its author publishes it and install it like any addon, then restart the game. Its guides appear in the guide menu under Community guides, with the author's name. The switch on its row above turns it on or off."] = "Bir topluluk eklentisini yazarı nerede yayımlıyorsa oradan al, her eklenti gibi kur ve oyunu yeniden başlat. Rehberleri, rehber menüsünde Topluluk rehberleri altında yazarın adıyla görünür. Yukarıdaki satırındaki anahtar onu açar ya da kapatır."
L["Each community addon is made and supported by its author: report its problems to them, not to Polestar. It is an addon like any other, so install community addons from authors you trust."] = "Her topluluk eklentisini yazarı yapar ve destekler: sorunlarını Polestar'a değil, yazarına bildir. Diğerleri gibi bir eklentidir; bu yüzden topluluk eklentilerini güvendiğin yazarlardan kur."
L["Anyone can make a community addon with Polestar's own tools."] = "Herkes Polestar'ın kendi araçlarıyla bir topluluk eklentisi yapabilir."
L["Community guides, explained"] = "Topluluk rehberleri nedir"
L["Installed"] = "Yüklü"
L["Read more:"] = "Devamı:"
L["Read more: docs/GUIDE_PACKS.md in Polestar's source"] = "Devamı: Polestar kaynak kodunda docs/GUIDE_PACKS.md"
