L["No zone called %s."] = "%s adında bölge yok."
L["/way [zone] x y [title], with x and y from 0 to 100; /way reset clears it."] = "/way [bölge] x y [başlık]; x ve y 0 ile 100 arasında; /way reset temizler."
L["No map %s."] = "%s haritası yok."
L["/way is off: turn on Let other addons set waypoints in Polestar's settings."] = "/way kapalı: Polestar ayarlarında “Diğer eklentiler yol noktası koyabilsin”i aç."
L["Shift-click a map to go there"] = "Gitmek için haritaya Shift+tık"
L["Shift-click the world map or minimap and the arrow takes you there; Alt-click works over map icons. Click the spot again to clear it."] = "Dünya haritasına ya da mini haritaya Shift+tık yap, ok seni oraya götürsün; harita simgelerinin üstünde Alt+tık çalışır. Temizlemek için noktaya yeniden tıkla."
L["Let other addons set waypoints"] = "Diğer eklentiler yol noktası koyabilsin"
L["Without TomTom installed, waypoints other addons set through TomTom, and /way, point Polestar's arrow. Addons that expect TomTom's own settings may not work with it on."] = "TomTom yüklü değilken, diğer eklentilerin TomTom üzerinden koyduğu yol noktaları ve /way, Polestar'ın okunu yönlendirir. TomTom'un kendi ayarlarını bekleyen eklentiler bu açıkken çalışmayabilir."
L["Follow TomTom's arrow"] = "TomTom'un okunu izle"
L["With TomTom installed, the arrow goes wherever TomTom's arrow points, routed like any goal."] = "TomTom yüklüyken ok, TomTom'un okunun gösterdiği yere, her hedef gibi rotalanarak gider."
L["Route style"] = "Rota stili"
L["Fastest: the shortest walk, over hills and across fields. Balanced: roads that aren't much longer, and round hills. Roads: stays on roads even when they're longer; the safest way, not the quickest."] = "En hızlı: tepelerin üstünden ve tarlaların içinden en kısa yürüyüş. Dengeli: çok uzun olmayan yollar ve tepelerin çevresinden. Yollar: daha uzun olsa da yollardan ayrılmaz; en güvenli yol, en hızlısı değil."
L["Fastest"] = "En hızlı"
L["Balanced"] = "Dengeli"
L["Roads"] = "Yollar"

