-- Quests/Party.lua
L["%s done"] = "%s tamam"
L["Not on this quest: %s"] = "Bu görevde değil: %s"
L["Party"] = "Grup"
L["Share my quest progress with my party"] = "Görev ilerlememi grubumla paylaş"
L["Show my party's progress in the guide"] = "Grubumun ilerlemesini rehberde göster"
L["%s has a newer %s guide pack (%s; yours is %s)."] = "%s daha yeni bir %s rehber paketine sahip (%s; seninki %s)."
L["%s: 1 step ahead"] = "%s: 1 adım önde"
L["%s: %d steps ahead"] = "%s: %d adım önde"
L["%s: 1 step behind"] = "%s: 1 adım geride"
L["%s: %d steps behind"] = "%s: %d adım geride"
L["%s: on this step"] = "%s: bu adımda"
L["Still at it: %s"] = "Hâlâ uğraşıyor: %s"
L["already done"] = "zaten yapılmış"
L["quest log full"] = "görev günlüğü dolu"
L["can't take it"] = "alamıyor"
L["too far to share"] = "paylaşmak için çok uzak"
L["level too low"] = "seviyesi çok düşük"
L["another class"] = "başka bir sınıf"
L["another race"] = "başka bir ırk"
L["level %d, needs %d"] = "seviye %d, gereken %d"
L["Waiting on %s"] = "%s bekleniyor"
L["Everyone's ready"] = "Herkes hazır"
L["Waiting on %s: %s"] = "%s bekleniyor: %s"
L["%s still needs %d %s"] = "%s için hâlâ %d %s gerekli"
L["%s (%s)"] = "%s (%s)"
L["%s: other guide"] = "%s: başka rehber"
L["Party: %s"] = "Grup: %s"
L["For %s: she still needs %d"] = "%s için: hâlâ %d gerekli"
L["For %s: he still needs %d"] = "%s için: hâlâ %d gerekli"
L["For %s: still needs %d"] = "%s için: hâlâ %d gerekli"
L["Party members who run Polestar see your counts under their quest goals, your step and your level. Hidden addon messages to your party only; nothing goes to chat."] = "Polestar kullanan grup üyeleri senin sayılarını kendi görev hedeflerinin altında, adımını ve seviyeni görür. Yalnızca grubuna giden gizli eklenti mesajları; sohbete hiçbir şey gitmez."
L["Their counts under your quest goals, and who lacks a quest you took, with a Share button."] = "Onların sayıları senin görev hedeflerinin altında, ve aldığın bir görevi kimin almadığı, bir “Paylaş” düğmesiyle."
L["Wait for the group"] = "Grubu bekle"
L["When a party member on your quest still needs an objective you finished, the step and its turn-in wait and the arrow leads to what they need. Members in another zone or offline for 2 minutes don't hold you; the party line offers Go on without them."] = "Görevindeki bir grup üyesinin, senin bitirdiğin bir hedefe hâlâ ihtiyacı varsa adım ve teslimi bekler, ok da onun ihtiyacına götürür. Başka bir bölgedeki ya da 2 dakikadır çevrimdışı olan üyeler seni bekletmez; grup satırı “Onlarsız devam et” seçeneğini sunar."
L["Say who still needs quest loot"] = "Görev loot'una kimin hâlâ ihtiyacı olduğunu söyle"
L["On a loot window or roll, a line under a quest item a party member still needs and you don't. Nothing is passed or said for you."] = "Bir loot penceresinde ya da zar atışında, bir grup üyesinin hâlâ ihtiyaç duyduğu ama senin duymadığın görev eşyasının altında bir satır. Senin yerine hiçbir şey pas geçilmez ya da söylenmez."
L["Party panel"] = "Grup paneli"
L["Opens by itself when someone in your party runs Polestar too: each member's level, step and what they still need of yours; click a name to point the arrow at them. Closed, it stays closed; /polestar party opens it again."] = "Grubundaki biri de Polestar kullandığında kendiliğinden açılır: her üyenin seviyesi, adımı ve seninkilerden hâlâ neye ihtiyaç duyduğu; oku ona çevirmek için bir ada tıkla. Kapatırsan kapalı kalır; /polestar party onu yeniden açar."
L["Tell my party about objectives and ready quests"] = "Hedefleri ve hazır görevleri grubuma söyle"
L["A party chat line with the quest's link when you finish its objectives, and one when the quest is ready to turn in. Everyone in the party sees it, Polestar or not. Never solo or in a raid."] = "Bir görevin hedeflerini bitirdiğinde görevin bağlantısıyla bir grup sohbeti satırı, görev teslime hazır olduğunda da bir satır. Gruptaki herkes görür, Polestar'ı olsun olmasın. Tekken ya da raidde asla."
L["Tell my party when I loot an item that starts a quest"] = "Görev başlatan bir eşya loot edince grubuma söyle"
L["A party chat line with the item's link and the quest it starts."] = "Eşyanın bağlantısı ve başlattığı görevle bir grup sohbeti satırı."
L["Show my own lines in my chat too"] = "Kendi satırlarımı kendi sohbetimde de göster"
L["Off: your party sees the lines Polestar says for you, and your chat stays clear of them."] = "Kapalıyken: grubun, Polestar'ın senin adına söylediği satırları görür; senin sohbetin onlardan temiz kalır."
L["Hide other players' Polestar lines"] = "Diğer oyuncuların Polestar satırlarını gizle"
L["Party members' Polestar lines leave your chat. Shown, they carry Polestar's star."] = "Grup üyelerinin Polestar satırları sohbetinden çıkar. Gösterildiklerinde Polestar'ın yıldızını taşırlar."
L["Only when someone in the party doesn't have Polestar"] = "Yalnızca gruptaki birinde Polestar yoksa"
L["Nothing goes to chat while everyone in your party runs Polestar: they see your progress in their guide."] = "Grubundaki herkes Polestar kullanırken sohbete hiçbir şey gitmez: ilerlemeni kendi rehberlerinde görürler."
L["%s asks you to sync to their guide."] = "%s, rehberine eşitlenmeni istiyor."
L["You'll switch to %s."] = "%s rehberine geçeceksin."
L["Their step: %s"] = "Onun adımı: %s"
L["You're past their step: your guide stays where you are."] = "Onun adımını geçtin: rehberin olduğun yerde kalır."
L["%s is past these, which you haven't done: %s"] = "%s şunları geçti, sen yapmadın: %s"
L["You've done these already, so your guide passes them: %s"] = "Bunları zaten yaptın, rehberin onları geçer: %s"
L["%s asked you to sync to their guide, but it isn't for your character or your copy lacks their step."] = "%s rehberine eşitlenmeni istedi, ama o rehber karakterin için değil ya da senin kopyanda onun adımı yok."
L["No room for another guide tab: close one, then ask %s again."] = "Bir rehber sekmesine daha yer yok: birini kapat, sonra %s oyuncusundan yeniden iste."
L["%s synced to your guide."] = "%s senin rehberine eşitlendi."
L["%s declined to sync."] = "%s eşitlemeyi reddetti."
L["%s can't sync: your guide isn't for their character, or their copy lacks your step."] = "%s eşitlenemiyor: rehberin onun karakteri için değil ya da onun kopyasında senin adımın yok."
L["%s is already on your step."] = "%s zaten senin adımında."
L["No one else in your party has been heard running Polestar yet."] = "Grubundaki başka kimsenin Polestar kullandığı henüz duyulmadı."
L["You have no step to sync to: open a guide you haven't finished."] = "Eşitlenecek adımın yok: bitirmediğin bir rehber aç."
L["You asked a moment ago: wait %d seconds."] = "Az önce istedin: %d saniye bekle."
L["The game didn't send it: try again in a moment."] = "Oyun bunu göndermedi: birazdan yeniden dene."
L["Asked your party to sync to your step. Each of them chooses."] = "Grubundan adımına eşitlenmesi istendi. Her biri kendisi seçer."
L["%s asked you to sync to their guide; that prompt can't show with the gamepad interface."] = "%s rehberine eşitlenmeni istedi; bu soru gamepad arayüzünde gösterilemiyor."
L["%s is on Polestar %s: your guides can differ. A newer version is out."] = "%s, Polestar %s kullanıyor: rehberleriniz farklı olabilir. Daha yeni bir sürüm çıktı."
L["%s is on Polestar %s: your guides can differ."] = "%s, Polestar %s kullanıyor: rehberleriniz farklı olabilir."
L["Party sync is on: you and your party see each other's quest progress. Turn it off in Options."] = "Grup eşitleme açık: sen ve grubun birbirinizin görev ilerlemesini görürsünüz. Seçenekler'den kapatabilirsin."
L["Ask other players' Polestar which version it is"] = "Diğer oyuncuların Polestar'ına sürümünü sor"
L["Up to 10 hidden addon whispers a session, to players of your faction you target or mouse over outside cities, combat and dungeons, and an answer to theirs: only the version number, so Polestar can tell you when a newer one is out. Off: none sent or answered."] = "Oturum başına en fazla 10 gizli eklenti fısıltısı; şehirler, savaş ve zindanlar dışında hedef aldığın ya da fareyle üzerine geldiğin kendi tarafından oyunculara, bir de onlarınkine yanıt: yalnızca sürüm numarası; böylece Polestar daha yenisi çıkınca sana söyleyebilir. Kapalı: hiçbiri gönderilmez ya da yanıtlanmaz."

