L["1 point is spent outside this plan. Its marks on the talent frame show where; a respec puts you back on it."] = "1 puan bu planın dışında harcanmış. Yetenek penceresindeki işaretler nerede olduğunu gösterir; respec seni plana geri döndürür."
L["%d points are spent outside this plan. Its marks on the talent frame show where; a respec puts you back on it."] = "%d puan bu planın dışında harcanmış. Yetenek penceresindeki işaretler nerede olduğunu gösterir; respec seni plana geri döndürür."
L["1 point to spend. Next: %s."] = "Harcanacak 1 puan. Sıradaki: %s."
