L["This plan no longer matches the game's talent tree (missing: %s). It is shown as written, without marks on the talent frame, until Polestar is updated."] = "Bu plan artık oyunun yetenek ağacıyla uyuşmuyor (eksik: %s). Polestar güncellenene dek yazıldığı gibi, yetenek penceresinde işaret olmadan gösteriliyor."
