L["%s, then press a button, or hold one and press another. Tap %s to cancel, hold it to bind %s. %s unbinds."] = "%s, sonra bir düğmeye bas ya da birini basılı tutup başka birine bas. İptal için %s düğmesine dokun, %s atamak için basılı tut. %s atamayı kaldırır."
L["%s, then press a button. Tap %s to cancel, hold it to bind %s. %s unbinds."] = "%s, sonra bir düğmeye bas. İptal için %s düğmesine dokun, %s atamak için basılı tut. %s atamayı kaldırır."
L["Click, then press a key; Escape cancels. Right-click unbinds."] = "Tıkla, sonra bir tuşa bas; Escape iptal eder. Sağ tık atamayı kaldırır."
