L["Gamepad"] = "Oyun kumandası"
L["Navigation"] = "Gezinme"
L["Key bindings"] = "Tuş atamaları"
L["Play Polestar with a gamepad: its windows, its buttons and your bindings. The bindings take keys too."] = "Polestar'ı kumandayla oyna: pencereleri, düğmeleri ve atamaların. Atamalar klavye tuşlarını da alır."
L["Your gamepad"] = "Kumandan"
L["Button names"] = "Düğme adları"
L["The names and shapes Polestar shows for your gamepad's buttons. Automatic reads them off the gamepad."] = "Polestar'ın kumandanın düğmeleri için gösterdiği adlar ve şekiller. Otomatik, bunları kumandadan okur."
L["Automatic"] = "Otomatik"
L["Xbox (A, B, X, Y)"] = "Xbox (A, B, X, Y)"
L["PlayStation (shapes)"] = "PlayStation (şekiller)"
L["Navigate Polestar's windows"] = "Polestar pencerelerinde gezin"
L["While a Polestar window is open, the D-pad moves through it, A selects, B closes, LB and RB change tabs, Y restores a default. Out of combat; the game gets every button back when the window closes."] = "Bir Polestar penceresi açıkken yön tuşları içinde gezinir, A seçer, B kapatır, LB ve RB sekme değiştirir, Y varsayılanı geri getirir. Savaş dışında; pencere kapanınca oyun tüm düğmeleri geri alır."
L["Button hints"] = "Düğme ipuçları"
L["A bar under the window says what each button does, and B sits on the close button."] = "Pencerenin altındaki bir çubuk her düğmenin ne yaptığını söyler; B kapatma düğmesinin üstündedir."
L["The guide"] = "Rehber"
L["Quest buttons"] = "Görev düğmeleri"
L["The guide window holds the gamepad until B: the D-pad picks a line, A points the arrow there or uses the item, X shows its details, LB and RB change steps, Y minimizes the window. A window that opened by itself, such as a route choice, waits for this button before it takes the gamepad."] = "Rehber penceresi B'ye basana dek kumandayı tutar: yön tuşları bir satır seçer, A oku oraya çevirir ya da eşyayı kullanır, X ayrıntıları gösterir, LB ve RB adım değiştirir, Y pencereyi küçültür. Rota seçimi gibi kendiliğinden açılan bir pencere, kumandayı almadan önce bu düğmeyi bekler."
L["Browsing the guide needs the game's gamepad interface (Options, Gamepad, Enable Gamepad UI), or Use with the keyboard and mouse on Polestar's Gamepad page with a gamepad plugged in."] = "Rehberde gezinmek için oyunun kumanda arayüzü (Options, Gamepad, Enable Gamepad UI) ya da kumanda takılıyken Polestar'ın Oyun kumandası sayfasındaki “Klavye ve fareyle kullan” gerekir."
L["Use with the keyboard and mouse"] = "Klavye ve fareyle kullan"
L["Off, Polestar uses the gamepad only with the game's gamepad interface (Options, Gamepad, Enable Gamepad UI). On, also with the keyboard and mouse interface, while the gamepad is turned on in the game's options and plugged in."] = "Kapalıyken Polestar kumandayı yalnızca oyunun kumanda arayüzüyle (Options, Gamepad, Enable Gamepad UI) kullanır. Açıkken, kumanda oyunun seçeneklerinde açık ve takılıyken klavye ve fare arayüzüyle de kullanır."

