-- Talents/Builds.lua
-- L["Holy"] = ""
-- L["Protection"] = ""
L["Level as Retribution (quickest solo, with a two-hander and Seal of Command) or Protection (safe group pulls, dungeon-tank ready). Holy suits raids; it can level through its melee build, more slowly, if you want to heal dungeons on the way."] = "Retribution (iki elli silah ve Seal of Command ile en hızlı solo) ya da Protection (güvenli toplu çekişler, zindan tanklığına hazır) olarak seviye atla. Holy raidlere uygun; yolda zindanlarda heal yapmak istiyorsan yakın dövüş planıyla, daha yavaş, seviye atlayabilir."
L["Start with Divine Intellect: more mana means you can melee and still cover your own (or a group's) healing."] = "Divine Intellect ile başla: daha çok mana, hem yakın dövüşte vurup hem kendi (ya da grubun) iyileştirmeni karşılayabilmen demek."
L["Improved Seals raises every seal and Judgement here, which is where Holy's leveling damage comes from."] = "Improved Seals buradaki her seal'i ve Judgement'ı güçlendirir; Holy'nin seviye atlarken hasarı buradan gelir."
L["Reverence keeps a trickle of regen going while casting; three ranks unlock Illumination."] = "Reverence büyü yaparken az da olsa yenilenmeyi sürdürür; üç derece Illumination'ı açar."
L["Illumination refunds mana on critical heals and is the heart of Holy's staying power."] = "Illumination kritik iyileştirmelerde manayı geri verir ve Holy'nin dayanıklılığının kalbidir."
L["Holy Shock is a talent on Forever: an instant heal or Holy hit, handy for emergencies and for pulling."] = "Holy Shock, Forever'da bir yetenek: anında bir iyileştirme ya da Holy vuruşu; acil durumlarda ve çekişte işe yarar."
L["Holy Power raises Holy Shock's crit chance, feeding Illumination and Infusion of Light."] = "Holy Power, Holy Shock'ın kritik şansını artırır; Illumination ve Infusion of Light'ı besler."
L["Light's Vigil turns Holy Shock into a group-heal burst; this is the signature Forever Holy talent."] = "Light's Vigil, Holy Shock'ı ani bir grup iyileştirmesine çevirir; Forever Holy'sinin imza yeteneği budur."
L["The remaining 20 points go to Retribution: cheaper spells and more melee crit while questing, ending in Seal of Command."] = "Kalan 20 puan Retribution'a gider: görev yaparken daha ucuz büyüler ve daha çok yakın dövüş kritiği, sonunda Seal of Command."
L["Open with Redoubt: blocking pays off at once, and Shield Specialization needs all five ranks."] = "Redoubt ile başla: bloklamak hemen işe yarar ve Shield Specialization beş derecenin hepsini ister."
L["Precision and Anticipation help you land hits and dodge them while questing with a shield."] = "Precision ve Anticipation, kalkanla görev yaparken vuruşlarını isabet ettirmene ve vuruşlardan kaçmana yardım eder."
L["Improved Seal of Fury and Improved Righteous Fury begin the mana and mitigation cycle Forever tanking is built on."] = "Improved Seal of Fury ve Improved Righteous Fury, Forever tanklığının dayandığı mana ve hasar azaltma döngüsünü başlatır."
L["Around 20 points in, you match the usual dungeon-tank setup: Shield Specialization, Sacred Duty and Swift Judgement are complete."] = "20 puan civarında olağan zindan tankı düzenine ulaşırsın: Shield Specialization, Sacred Duty ve Swift Judgement tamamdır."
L["Templar's Bulwark is an absorb cooldown that scales with your health, and Holy Shield later in the plan requires it."] = "Templar's Bulwark, canınla ölçeklenen bir emme cooldown'ı; plandaki sonraki Holy Shield onu gerektirir."
L["Iron Creed adds threat and damage reduction to Holy Strike while Righteous Fury is active."] = "Iron Creed, Righteous Fury açıkken Holy Strike'a tehdit ve hasar azaltma ekler."
L["Holy Shield is the capstone: more block uptime, with Holy damage each time you block. Ideal for pulling packs."] = "Zirve yetenek Holy Shield: daha çok blok süresi, her blokta Holy hasarı. Toplu çekişler için ideal."
L["Leftover points buy armor, a quicker Hammer of Justice, and Holy Strength and seal damage for leveling."] = "Artan puanlar zırha, daha sık Hammer of Justice'e, seviye atlamak için Holy Strength'e ve seal hasarına gider."
L["Benediction lowers the mana cost of Judgement, Holy Strike and seals, so you rest less between fights."] = "Benediction; Judgement, Holy Strike ve seal'lerin mana maliyetini düşürür, böylece dövüşler arasında daha az dinlenirsin."
L["Seal of Command is the main two-hander seal for leveling; take it as soon as it opens."] = "Seal of Command, seviye atlarken iki elli silahın ana seal'i; açılır açılmaz al."
L["Sanctified Judgement gives mana back and is the prerequisite arrow for Vengeance."] = "Sanctified Judgement mana geri verir ve Vengeance'ın ön koşul okudur."
L["Sacred Arbiter strengthens Holy Strike and keeps Judgements rolling, and completes the 20 points row 5 asks for."] = "Sacred Arbiter, Holy Strike'ı güçlendirir, Judgement'ları sürdürür ve 5. sıranın istediği 20 puanı tamamlar."
L["Vengeance, then Two-Handed Weapon Specialization: the crit-driven damage core of the two-hander plan."] = "Önce Vengeance, sonra Two-Handed Weapon Specialization: iki elli planın kritiğe dayalı hasar çekirdeği."
L["Pursuit of Justice adds run speed. Champion of the Light is left out while the Retribution Aura spell-power bug keeps spell damage low."] = "Pursuit of Justice koşu hızı ekler. Retribution Aura'nın büyü gücü hatası büyü hasarını düşük tuttuğu sürece Champion of the Light alınmıyor."
L["Twist of Light makes swapping seals cheaper and adds seal echoes; it is Forever's seal-twisting talent."] = "Twist of Light seal değiştirmeyi ucuzlatır ve seal yankıları ekler; Forever'ın seal-twisting yeteneğidir."
L["Spare points go to Divine Strength and Holy's Improved Seals for damage, then Deflection for survival."] = "Artan puanlar hasar için Divine Strength'e ve Holy'deki Improved Seals'e, sonra hayatta kalmak için Deflection'a gider."
L["Level as Combat with a sword (Riposte, Blade Flurry, Adrenaline Rush) for the steadiest kills, or Assassination with daggers and poisons (Mutilate). Subtlety's Hemorrhage plan suits stealth openers and is slower solo."] = "En istikrarlı öldürmeler için kılıçla Combat (Riposte, Blade Flurry, Adrenaline Rush) ya da hançer ve zehirlerle Assassination (Mutilate) olarak seviye atla. Subtlety'nin Hemorrhage planı gizlilikten açılışlara uygun, solo daha yavaş."
L["Malice first: crit for every attack and poison, and it opens Lethality."] = "Önce Malice: her saldırı ve zehir için kritik; Lethality'yi de açar."
L["Ruthlessness gives finishers a chance at a free combo point; Murder adds damage against humanoids and giants."] = "Ruthlessness bitirici hamlelere bedava combo puanı şansı verir; Murder insansılara ve devlere karşı hasar ekler."
L["Relentless Strikes refunds energy from finishers, so fights flow without waiting."] = "Relentless Strikes bitirici hamlelerden enerji geri verir, böylece dövüşler beklemeden akar."
L["Improved Poisons puts poisons on more often and makes charges last; take them as soon as you train poisons."] = "Improved Poisons zehirlerin daha sık işlemesini ve yüklerin daha uzun sürmesini sağlar; zehirleri öğrenir öğrenmez al."
L["Mutilate is Forever's dual-wield dagger strike: two combo points a use, and more damage on poisoned targets."] = "Mutilate, Forever'ın çift hançerli vuruşu: her kullanımda iki combo puanı, zehirli hedeflere daha çok hasar."
L["Seal Fate turns crits into extra combo points; with Malice and Lethality it is the core of the build."] = "Seal Fate kritikleri ek combo puanına çevirir; Malice ve Lethality ile planın çekirdeğidir."
L["Venom is the capstone: a finisher that strengthens your poisons for a while."] = "Zirve yetenek Venom: zehirlerini bir süre güçlendiren bir bitirici hamle."
L["The last 20 points go to Combat: cheaper Sinister Strikes, a stronger Eviscerate, more hit and parry, Riposte and a stronger off-hand."] = "Son 20 puan Combat'a gider: daha ucuz Sinister Strike, daha güçlü Eviscerate, daha çok isabet ve savuşturma, Riposte ve daha güçlü ikinci el."
L["Improved Sinister Strike first: cheaper Sinister Strikes are the biggest early gain."] = "Önce Improved Sinister Strike: daha ucuz Sinister Strike en büyük erken kazançtır."
L["Precision helps you hit more often; it also opens Dual Wield Specialization."] = "Precision daha sık isabet ettirmeni sağlar; Dual Wield Specialization'ı da açar."
L["Riposte follows each parry with a heavy strike that also disarms."] = "Riposte her savuşturmanın ardından silahsızlandıran ağır bir vuruş yapar."
L["Blade Flurry is faster attacks and cleave on demand; Hack and Slash then adds extra attacks with swords and axes."] = "Blade Flurry istediğinde daha hızlı saldırı ve çoklu vuruş demek; ardından Hack and Slash kılıç ve baltalarla ek saldırılar ekler."
L["Adrenaline Rush is the capstone: double energy for 15 seconds, enough for a second mob."] = "Zirve yetenek Adrenaline Rush: 15 saniye boyunca iki kat enerji, ikinci bir yaratık için yeter."
L["The remaining points go to Assassination for crit, free combo points, energy refunds and Lethality."] = "Kalan puanlar kritik, bedava combo puanı, enerji iadesi ve Lethality için Assassination'a gider."
L["Opportunity adds damage to Backstab, Ambush and Garrote, your stealth openers."] = "Opportunity, gizlilikten açılışların olan Backstab, Ambush ve Garrote'a hasar ekler."
L["Improved Ambush and Initiative make the opener the fight: a likely crit and extra combo points."] = "Improved Ambush ve Initiative açılışı dövüşün kendisi yapar: muhtemel bir kritik ve ek combo puanları."
L["Serrated Blades ignores armor and is the way into Hemorrhage."] = "Serrated Blades zırhı yok sayar ve Hemorrhage'a giden yoldur."
L["Hemorrhage is your main builder from here, with any weapon, and it adds to Rupture damage."] = "Buradan sonra her silahla ana combo kurucun Hemorrhage; Rupture hasarını da artırır."
L["Quietus adds damage to Hemorrhage and Ghostly Strike on a low-health target, finishing mobs sooner."] = "Quietus, canı az olan hedefte Hemorrhage ve Ghostly Strike'a hasar ekler; yaratıkları daha çabuk bitirirsin."
L["Thousand Cuts is the capstone: Rupture ticks make your next Hemorrhage cheaper."] = "Zirve yetenek Thousand Cuts: Rupture tikleri bir sonraki Hemorrhage'ı ucuzlatır."
L["Level as Arms with a two-hander (Mortal Strike, Sweeping Strikes) or Fury (Enrage, Death Wish, then Flurry and Bloodthirst with two weapons). Protection is slower alone but ready to tank any dungeon on the way."] = "İki elli silahla Arms (Mortal Strike, Sweeping Strikes) ya da Fury (Enrage, Death Wish, sonra iki silahla Flurry ve Bloodthirst) olarak seviye atla. Protection tek başına daha yavaş ama yoldaki her zindanı tanklamaya hazır."
L["Improved Heroic Strike first: Heroic Strike is your main rage dump, and a cheaper one means more of them."] = "Önce Improved Heroic Strike: Heroic Strike ana rage harcaman; daha ucuz olması daha çok kullanman demek."
L["Improved Tactical Mastery keeps rage when you swap stances, so Charge, Overpower and Battle Stance openers cost you nothing."] = "Improved Tactical Mastery duruş değiştirirken rage'ini korur; böylece Charge, Overpower ve Battle Stance açılışları sana bir şeye mal olmaz."
L["Anger Management is a steady rage trickle in every fight; on Forever it also slows rage loss between pulls."] = "Anger Management her dövüşte düzenli bir rage akışı sağlar; Forever'da çekişler arasındaki rage kaybını da yavaşlatır."
L["Improved Rend and Deep Wounds turn your crits into bleeds; Deep Wounds also opens Impale."] = "Improved Rend ve Deep Wounds kritiklerini kanamaya çevirir; Deep Wounds, Impale'i de açar."
L["Sweeping Strikes makes two-mob pulls quick; Weaponmaster then adds crit, armor penetration or extra attacks for your weapon type."] = "Sweeping Strikes iki yaratıklı çekişleri hızlandırır; ardından Weaponmaster silah türüne göre kritik, zırh delme ya da ek saldırı ekler."
L["Improved Slam stops Slam from resetting your swing: a free hit between big two-hander swings."] = "Improved Slam, Slam'in vuruş zamanlayıcını sıfırlamasını engeller: büyük iki elli vuruşlar arasında bedava bir vuruş."
L["Mortal Strike is the capstone and your hardest-hitting strike for the rest of the climb."] = "Zirve yetenek Mortal Strike; seviye yolculuğunun geri kalanında en sert vuruşun."
L["The last 20 points go to Fury: Cruelty and Unbridled Wrath give more crit and more rage."] = "Son 20 puan Fury'ye gider: Cruelty ve Unbridled Wrath daha çok kritik ve daha çok rage verir."
L["Enrage finishes the plan: a damage boost that is often up while you take hits."] = "Planı Enrage bitirir: vuruş alırken sık sık açık olan bir hasar artışı."
L["Cruelty first: more crit for every build, and the way into the Fury tree."] = "Önce Cruelty: her plan için daha çok kritik ve Fury ağacına giden yol."
L["Unbridled Wrath means more rage from every swing, which matters most with two fast weapons."] = "Unbridled Wrath her vuruştan daha çok rage demek; en çok iki hızlı silahla önemlidir."
L["Piercing Howl stops runners and lets you walk away from a bad pull."] = "Piercing Howl kaçanları durdurur ve kötü bir çekişten uzaklaşmanı sağlar."
L["Enrage raises your physical damage after you are hit, so it is often up while you take hits."] = "Enrage vuruş aldıktan sonra fiziksel hasarını artırır; bu yüzden vuruş alırken sık sık açıktır."
L["Death Wish is a big cooldown for elites and a fear breaker; it also opens Flurry."] = "Death Wish elitler için büyük bir cooldown ve korkuyu kırar; Flurry'yi de açar."
L["Dual Wield Specialization: more off-hand damage and rage now that you carry two weapons."] = "Dual Wield Specialization: artık iki silah taşıdığın için daha çok ikinci el hasarı ve rage."
L["Bloodthirst is the capstone: a strong instant attack and a little run speed between mobs."] = "Zirve yetenek Bloodthirst: güçlü, anında bir saldırı ve yaratıklar arasında biraz koşu hızı."
L["Gore Drinker turns your rage cooldowns into self-healing, so you rest less."] = "Gore Drinker rage cooldown'larını kendini iyileştirmeye çevirir, böylece daha az dinlenirsin."
L["Spare points go to Arms for cheaper Heroic Strikes, stance-swap rage, Anger Management and Deep Wounds."] = "Artan puanlar daha ucuz Heroic Strike, duruş değiştirirken rage, Anger Management ve Deep Wounds için Arms'a gider."
L["Shield Specialization: more blocks, and on Forever each block also gives rage."] = "Shield Specialization: daha çok blok; Forever'da her blok rage de verir."
L["Improved Revenge makes Revenge, which you can use after each block, a real damage hit."] = "Improved Revenge, her bloktan sonra kullanabildiğin Revenge'i gerçek bir hasar vuruşuna çevirir."
L["Last Stand is your emergency cooldown when a pull goes wrong."] = "Last Stand, bir çekiş kötü gittiğinde acil durum cooldown'ın."
L["Vanguard lets you Charge from Defensive Stance: no stance dance to open a pull."] = "Vanguard, Defensive Stance'tayken Charge kullanmanı sağlar: çekişe başlamak için duruş değiştirmek yok."
L["Concussion Blow is a stun on demand, for an interrupt or to reach a runner."] = "Concussion Blow istediğinde sersemletir; büyü kesmek ya da kaçana yetişmek için."
L["Bastion adds damage to everything you do with a shield on; it is what makes Protection level well."] = "Bastion kalkan takılıyken yaptığın her şeye hasar ekler; Protection'ın iyi seviye atlamasını sağlayan budur."
L["Shield Slam is the capstone: a big hit that grows with your block value, and high threat for dungeons."] = "Zirve yetenek Shield Slam: blok değerinle büyüyen büyük bir vuruş ve zindanlar için yüksek tehdit."
L["Defiance, Improved Thunder Clap and Improved Shield Wall round out the tank kit for dungeons."] = "Defiance, Improved Thunder Clap ve Improved Shield Wall zindanlar için tank donanımını tamamlar."
L["The last 10 points go to Arms: cheaper Heroic Strikes and Improved Tactical Mastery for swaps to Battle Stance."] = "Son 10 puan Arms'a gider: daha ucuz Heroic Strike ve Battle Stance'e geçişler için Improved Tactical Mastery."
L["Level as Frost (the safest: slows, freezes and Ice Barrier) or Fire (more damage, with Pyroblast openers and Blast Wave). Arcane builds around Arcane Blast and Arcane Power and wants more mana between pulls."] = "Frost (en güvenlisi: yavaşlatma, dondurma ve Ice Barrier) ya da Fire (daha çok hasar, Pyroblast açılışları ve Blast Wave) olarak seviye atla. Arcane, Arcane Blast ve Arcane Power üzerine kurulur ve çekişler arasında daha çok mana ister."
L["Improved Channeling first: Arcane Missiles, and later Arcane Blast, keep going when a mob hits you."] = "Önce Improved Channeling: bir yaratık sana vurunca Arcane Missiles ve sonra Arcane Blast kesilmeden devam eder."
L["Arcane Concentration gives free casts now and then, and opens Arcane Meditation."] = "Arcane Concentration ara sıra bedava büyü sağlar ve Arcane Meditation'ı açar."
L["Arcane Blast is Forever's Arcane builder: each cast adds spell power for the next."] = "Arcane Blast, Forever'ın Arcane kurucusu: her kullanım bir sonrakine büyü gücü ekler."
L["Missile Barrage: Arcane Blast, Arcane Wrath, Fireball and Frostbolt can make your next Arcane Missiles faster and cheaper."] = "Missile Barrage: Arcane Blast, Arcane Wrath, Fireball ve Frostbolt bir sonraki Arcane Missiles'ı daha hızlı ve ucuz yapabilir."
L["Arcane Meditation keeps mana coming back while you cast, so you drink less."] = "Arcane Meditation büyü yaparken mananın gelmeye devam etmesini sağlar, böylece daha az içersin."
L["Arcane Wrath, opened by Arcane Blast, is a nuke that grows with your maximum mana. Its point does not count toward the Arcane tiers, so the plan spends 32 points in Arcane."] = "Arcane Blast'ın açtığı Arcane Wrath, en yüksek manana göre büyüyen bir saldırı büyüsü. Puanı Arcane sıralarına sayılmaz; bu yüzden plan Arcane'e 32 puan harcar."
L["Presence of Mind makes one spell instant: an opener, or a finisher on a runner."] = "Presence of Mind bir büyüyü anında yapar: bir açılış ya da kaçan bir yaratığa son vuruş."
L["Arcane Power is the capstone: more damage for more mana, best with Presence of Mind on a tough target."] = "Zirve yetenek Arcane Power: daha çok mana karşılığında daha çok hasar; zorlu bir hedefte Presence of Mind ile en iyisi."
L["The remaining 19 points go to Frost for a quicker Frostbolt, a shorter Frost Nova cooldown, longer slows and Ice Block."] = "Kalan 19 puan daha hızlı Frostbolt, daha kısa Frost Nova cooldown'ı, daha uzun yavaşlatmalar ve Ice Block için Frost'a gider."
L["Improved Fireball first: a faster Fireball is more damage every fight."] = "Önce Improved Fireball: daha hızlı Fireball her dövüşte daha çok hasar demek."
L["Ignite adds burn damage to every Fire crit."] = "Ignite her Fire kritiğine yanma hasarı ekler."
L["Pyroblast is a big opener from range; cast it first, then Fireball."] = "Pyroblast uzaktan büyük bir açılış; önce onu, sonra Fireball'ı kullan."
L["Master of Elements gives mana back on crits, so you rest less."] = "Master of Elements kritiklerde mana geri verir, böylece daha az dinlenirsin."
L["Critical Mass and Blast Wave: more crits, and an area attack and daze for when two mobs reach you."] = "Critical Mass ve Blast Wave: daha çok kritik; iki yaratık sana ulaşınca alan saldırısı ve sersemletme."
L["Fire Power raises your Fire damage for each of your Fire effects on the target: Ignite, Pyroblast's burn and the like."] = "Fire Power, hedefteki her Fire etkin için Fire hasarını artırır: Ignite, Pyroblast'ın yanması ve benzerleri."
L["Combustion is the capstone: a crit cooldown for elites and big pulls."] = "Zirve yetenek Combustion: elitler ve büyük çekişler için bir kritik cooldown'ı."
L["The last 20 points go to Arcane: a stronger wand for finishing mobs, then Arcane Concentration's free casts and Arcane Meditation's regen while casting."] = "Son 20 puan Arcane'e gider: yaratıkları bitirmek için daha güçlü wand, sonra Arcane Concentration'ın bedava büyüleri ve Arcane Meditation'ın büyü yaparken yenilenmesi."
L["Improved Frostbolt first: a faster Frostbolt is your main gain for the early levels."] = "Önce Improved Frostbolt: daha hızlı Frostbolt ilk seviyelerdeki ana kazancın."
L["Ice Shards makes Frost crits hit much harder."] = "Ice Shards, Frost kritiklerinin çok daha sert vurmasını sağlar."
L["Improved Frost Nova and Ice Block are your escapes: freeze, step back, keep casting."] = "Improved Frost Nova ve Ice Block kaçış yolların: dondur, geri çekil, büyüye devam et."
L["Shatter adds a large crit chance against frozen targets: Frost Nova, then Frostbolt or Ice Lance."] = "Shatter donmuş hedeflere karşı büyük bir kritik şansı ekler: önce Frost Nova, sonra Frostbolt ya da Ice Lance."
L["Ice Barrier is the capstone: an absorb shield that also stops pushback while you cast."] = "Zirve yetenek Ice Barrier: büyü yaparken geri itilmeyi de önleyen bir emme kalkanı."
L["Level as Affliction (instant Corruption, Siphon Life, drains) or Demonology (a tougher Voidwalker, Soul Link) for the fewest deaths. Destruction hits hardest with Conflagrate and Incinerate but needs more rest."] = "En az ölüm için Affliction (anında Corruption, Siphon Life, drain'ler) ya da Demonology (daha dayanıklı Voidwalker, Soul Link) olarak seviye atla. Destruction, Conflagrate ve Incinerate ile en sert vurur ama daha çok dinlenme ister."
L["Improved Corruption makes Corruption instant: the core of Affliction leveling."] = "Improved Corruption, Corruption'ı anında yapar: Affliction ile seviye atlamanın çekirdeği."
L["Improved Drains and Soul Harvest make Drain Life a heal and Drain Soul a mana return on kills."] = "Improved Drains ve Soul Harvest, Drain Life'ı bir iyileştirmeye, Drain Soul'u öldürmelerde mana iadesine çevirir."
L["Nightfall gives an instant Shadow Bolt now and then while your damage over time ticks."] = "Nightfall, zamana yayılan hasarın işlerken ara sıra anında bir Shadow Bolt verir."
L["Siphon Life adds another self-heal over time to the rotation."] = "Siphon Life rotasyona zamana yayılan bir kendini iyileştirme daha ekler."
L["Shadow Mastery adds damage to every Shadow spell."] = "Shadow Mastery her Shadow büyüsüne hasar ekler."
L["Wrack is the capstone: a strong channel that raises the damage the target takes from your other Shadow damage-over-time effects by 10%."] = "Zirve yetenek Wrack: hedefin diğer zamana yayılan Shadow etkilerinden aldığı hasarı %10 artıran güçlü bir kanal büyüsü."
L["The last 20 points go to Demonology: more Stamina, a tougher Voidwalker, quicker summons and Demonic Sacrifice."] = "Son 20 puan Demonology'ye gider: daha çok Stamina, daha dayanıklı Voidwalker, daha hızlı çağırma ve Demonic Sacrifice."
L["Demonic Embrace first: more Stamina means more Life Taps and fewer deaths."] = "Önce Demonic Embrace: daha çok Stamina, daha çok Life Tap ve daha az ölüm demek."
L["Improved Voidwalker makes your tank pet hold mobs better and shield you."] = "Improved Voidwalker tank pet'inin yaratıkları daha iyi tutmasını ve seni korumasını sağlar."
L["Soul Link shares your damage with your pet: with a Voidwalker you rarely die."] = "Soul Link aldığın hasarı pet'inle paylaşır: Voidwalker ile nadiren ölürsün."
L["Demonic Pact is the capstone: you keep Demonic Sacrifice's effect when you summon another demon."] = "Zirve yetenek Demonic Pact: başka bir iblis çağırdığında Demonic Sacrifice'ın etkisini korursun."
L["The rest goes to Affliction: an instant Corruption, stronger drains and Life Tap, and Nightfall's free Shadow Bolts."] = "Gerisi Affliction'a gider: anında Corruption, daha güçlü drain'ler ve Life Tap, ve Nightfall'un bedava Shadow Bolt'ları."
L["Bane first: faster Shadow Bolts and Immolates."] = "Önce Bane: daha hızlı Shadow Bolt ve Immolate."
L["Ruin makes Destruction crits hit much harder."] = "Ruin, Destruction kritiklerinin çok daha sert vurmasını sağlar."
L["Conflagrate turns your Immolate into burst damage; open with Immolate, then Conflagrate."] = "Conflagrate, Immolate'ini ani hasara çevirir; önce Immolate, sonra Conflagrate."
L["Incinerate is the capstone: a strong Fire nuke, best on an Immolated target."] = "Zirve yetenek Incinerate: güçlü bir Fire büyüsü; üstünde Immolate olan hedefte en iyisi."
L["Level as Feral Combat: Cat Form for quick kills, Bear Form for tough pulls, and no drinking. Balance kills from range with roots and Starfire; Restoration heals any dungeon and quests slowly with Wrath."] = "Feral Combat olarak seviye atla: hızlı öldürmeler için Cat Form, zor çekişler için Bear Form, içmeye gerek yok. Balance, kök salma ve Starfire ile uzaktan öldürür; Restoration her zindanda heal yapar ve Wrath ile yavaşça görev yapar."
L["Improved Wrath first: a faster, cheaper Wrath is most of your early damage."] = "Önce Improved Wrath: daha hızlı ve ucuz Wrath erken hasarının çoğu."
L["Moonglow and Nature's Majesty: cheaper spells and more crit."] = "Moonglow ve Nature's Majesty: daha ucuz büyüler ve daha çok kritik."
L["Improved Entangling Roots holds a mob in place while you nuke it from range."] = "Improved Entangling Roots, sen uzaktan büyü yaparken yaratığı yerinde tutar."
L["Nature's Grace speeds up your next spell after a crit."] = "Nature's Grace bir kritikten sonra sonraki büyünü hızlandırır."
L["Moonkin Form is the capstone: armor and more free casts while you nuke."] = "Zirve yetenek Moonkin Form: zırh ve saldırı büyüsü yaparken daha çok bedava büyü."
L["The last 20 points go to Restoration: fewer interrupted casts, Naturalist's damage, regen while casting and stronger heals."] = "Son 20 puan Restoration'a gider: daha az kesilen büyü, Naturalist'in hasarı, büyü yaparken yenilenme ve daha güçlü iyileştirmeler."
L["Ferocity first: cheaper Claw, Rake and Maul in both forms."] = "Önce Ferocity: iki formda da daha ucuz Claw, Rake ve Maul."
L["Savage Fury and Sharpened Claws add damage and crit in Cat and Bear Form."] = "Savage Fury ve Sharpened Claws, Cat Form ve Bear Form'da hasar ve kritik ekler."
L["Predatory Strikes adds attack power in forms; it scales with your level, not your gear."] = "Predatory Strikes formlarda saldırı gücü ekler; ekipmanınla değil seviyenle ölçeklenir."
L["Leader of the Pack adds crit for you and your group."] = "Leader of the Pack sana ve grubuna kritik ekler."
L["Berserk is the capstone: a cooldown that makes Primal Bite hit several targets."] = "Zirve yetenek Berserk: Primal Bite'ın birkaç hedefe vurmasını sağlayan bir cooldown."
L["The last 20 points go to Restoration: rage when you shift, Naturalist's damage, cheaper shifting and regen while casting."] = "Son 20 puan Restoration'a gider: form değiştirirken rage, Naturalist'in hasarı, daha ucuz form değiştirme ve büyü yaparken yenilenme."
L["Nature's Focus first: your casts go through while a mob hits you."] = "Önce Nature's Focus: bir yaratık sana vururken büyülerin kesilmez."
L["Reflection keeps mana coming back while casting, so you rest less."] = "Reflection büyü yaparken mananın gelmeye devam etmesini sağlar, böylece daha az dinlenirsin."
L["Swiftmend uses up a Rejuvenation or Regrowth for a big instant heal."] = "Swiftmend bir Rejuvenation ya da Regrowth'u harcayarak büyük, anında bir iyileştirme yapar."
L["Wild Growth is the capstone: a heal over time on your whole group."] = "Zirve yetenek Wild Growth: tüm grubuna zamana yayılan bir iyileştirme."
L["The last 20 points go to Balance so you can still kill quest mobs: a faster, cheaper Wrath, roots and more crit."] = "Görev yaratıklarını yine de öldürebilmen için son 20 puan Balance'a gider: daha hızlı ve ucuz Wrath, kök salma ve daha çok kritik."
L["Level as Enhancement (Flurry, Stormstrike, Maelstrom Weapon) for steady melee with few rests, or Elemental (Lightning Overload, Lava Burst) to kill from range. Restoration heals dungeons well and levels slowly alone."] = "Az dinlenmeyle istikrarlı yakın dövüş için Enhancement (Flurry, Stormstrike, Maelstrom Weapon) ya da uzaktan öldürmek için Elemental (Lightning Overload, Lava Burst) olarak seviye atla. Restoration zindanlarda iyi heal yapar, tek başına yavaş seviye atlar."
L["Concussion first: more damage from Lightning Bolt and Earth Shock, your two main spells."] = "Önce Concussion: iki ana büyün Lightning Bolt ve Earth Shock'tan daha çok hasar."
L["Elemental Focus makes some casts free, which is the main mana saver for the early levels."] = "Elemental Focus bazı büyüleri bedava yapar; ilk seviyelerdeki ana mana tasarrufu budur."
L["Lava Burst is a big Fire nuke, best after Flame Shock; Call of Flame makes it stronger."] = "Lava Burst büyük bir Fire büyüsü, Flame Shock'tan sonra en iyisi; Call of Flame onu güçlendirir."
L["Lightning Overload sometimes casts a second, smaller Lightning Bolt for free."] = "Lightning Overload bazen bedavaya ikinci, daha küçük bir Lightning Bolt atar."
L["Elemental Mastery is the capstone: for a while, quicker Lightning Bolts and Lava Bursts and no cooldown on Chain Lightning."] = "Zirve yetenek Elemental Mastery: bir süre daha hızlı Lightning Bolt ve Lava Burst, Chain Lightning'de cooldown yok."
L["The last 20 points go to Enhancement: more Intellect, more crit, a stronger Lightning Shield and cheaper Shocks."] = "Son 20 puan Enhancement'a gider: daha çok Intellect, daha çok kritik, daha güçlü Lightning Shield ve daha ucuz Shock'lar."
L["Thundering Strikes first: crit for spells and attacks, and the way into the tree."] = "Önce Thundering Strikes: büyüler ve saldırılar için kritik, ve ağaca giden yol."
L["Mental Dexterity turns your Intellect into attack power, so mana gear helps your melee too; it also opens Flurry."] = "Mental Dexterity, Intellect'ini saldırı gücüne çevirir; böylece mana ekipmanı yakın dövüşüne de yarar; Flurry'yi de açar."
L["Flurry speeds up your swings after a crit and is the core of Enhancement's damage."] = "Flurry bir kritikten sonra vuruşlarını hızlandırır ve Enhancement hasarının çekirdeğidir."
L["Stormstrike is an instant strike that raises the damage your next spells do."] = "Stormstrike, sonraki büyülerinin hasarını artıran anında bir vuruş."
L["Maelstrom Weapon makes your next Lightning Bolt faster and cheaper as you hit."] = "Maelstrom Weapon, sen vurdukça sonraki Lightning Bolt'u daha hızlı ve ucuz yapar."
L["Rage of the Farseer is the capstone: a big attack-speed cooldown for elites and pulls."] = "Zirve yetenek Rage of the Farseer: elitler ve çekişler için büyük bir saldırı hızı cooldown'ı."
L["The last 20 points go to Elemental for stronger Shocks, cheaper casts and more crit from spells."] = "Son 20 puan daha güçlü Shock'lar, daha ucuz büyüler ve büyülerden daha çok kritik için Elemental'e gider."
L["Tidal Focus first: cheaper heals, and more hit for your Lightning Bolts while you quest."] = "Önce Tidal Focus: daha ucuz iyileştirmeler, görev yaparken Lightning Bolt'ların için daha çok isabet."
L["Totemic Focus: cheaper totems, which you drop on every pull while leveling."] = "Totemic Focus: seviye atlarken her çekişte koyduğun totemler daha ucuz."
L["Mindfulness keeps half your mana regeneration going while casting."] = "Mindfulness büyü yaparken mana yenilenmenin yarısını sürdürür."
L["Nature's Swiftness makes one heal instant: your emergency button."] = "Nature's Swiftness bir iyileştirmeyi anında yapar: acil durum düğmen."
L["Riptide is the capstone: a quick heal with a heal over time for dungeons."] = "Zirve yetenek Riptide: zindanlar için zamana yayılan iyileştirmeli hızlı bir heal."
L["The last 20 points go to Elemental, so your Lightning Bolts and Shocks still kill while you quest."] = "Son 20 puan Elemental'e gider; böylece görev yaparken Lightning Bolt ve Shock'ların yine öldürür."
-- L["Feral Combat"] = ""
-- L["Restoration"] = ""
L["Level as Beast Mastery: your pet tanks and does much of the damage, so you rarely stop. Marksmanship hits harder from range with Careful Aim and Sniper Shot; Survival fights in melee with Predator's Edge and Lacerating Strikes."] = "Beast Mastery olarak seviye atla: pet'in tanklar ve hasarın çoğunu yapar, böylece nadiren durursun. Marksmanship, Careful Aim ve Sniper Shot ile uzaktan daha sert vurur; Survival, Predator's Edge ve Lacerating Strikes ile yakın dövüşte savaşır."
L["Deadly Aspects first: more from Aspect of the Hawk while your pet holds the mob."] = "Önce Deadly Aspects: pet'in yaratığı tutarken Aspect of the Hawk'tan daha çok fayda."
L["Unleashed Fury adds pet damage, and your pet is most of your damage."] = "Unleashed Fury pet hasarı ekler; hasarının çoğu pet'inden gelir."
L["Intimidation stuns through your pet: a breather when a mob turns on you."] = "Intimidation pet'in aracılığıyla sersemletir: bir yaratık sana döndüğünde nefes aldırır."
L["Bestial Wrath is the capstone: your pet's big damage cooldown."] = "Zirve yetenek Bestial Wrath: pet'inin büyük hasar cooldown'ı."
L["The last 20 points go to Marksmanship: more crit, attack power from Intellect, a shorter Rapid Fire and harder ranged crits."] = "Son 20 puan Marksmanship'e gider: daha çok kritik, Intellect'ten saldırı gücü, daha kısa Rapid Fire ve daha sert uzak kritikler."
L["Lethal Attacks first: crit for every shot."] = "Önce Lethal Attacks: her atış için kritik."
L["Careful Aim adds attack power from your Intellect."] = "Careful Aim, Intellect'inden saldırı gücü ekler."
L["Mortal Shots makes your ranged crits hit much harder."] = "Mortal Shots uzak kritiklerinin çok daha sert vurmasını sağlar."
L["Sniper Shot is the capstone: a long-range opener that hits hard."] = "Zirve yetenek Sniper Shot: sert vuran, uzun menzilli bir açılış."
L["The last 20 points go to Beast Mastery: a stronger Aspect of the Hawk and a tougher, harder-hitting pet."] = "Son 20 puan Beast Mastery'ye gider: daha güçlü Aspect of the Hawk ve daha dayanıklı, daha sert vuran bir pet."
L["Improved Tracking first: keep tracking on for its bonus against the mobs you quest on."] = "Önce Improved Tracking: görev yaptığın yaratıklara karşı bonusu için takibi açık tut."
L["Deterrence is a dodge and parry cooldown for melee fights that go wrong."] = "Deterrence, kötü giden yakın dövüşler için bir kaçınma ve savuşturma cooldown'ı."
L["Lightning Reflexes adds Agility: more attack power, crit and dodge."] = "Lightning Reflexes Agility ekler: daha çok saldırı gücü, kritik ve kaçınma."
L["Lacerating Strikes is the capstone: Mongoose Bite also makes the target bleed."] = "Zirve yetenek Lacerating Strikes: Mongoose Bite hedefi kanatır da."
L["Level as Shadow (Spirit Tap, Mind Flay, Shadowform) for the fastest kills and least drinking. Discipline levels with Smite and Penance behind a strong shield; Holy is the dungeon healer and slower alone."] = "En hızlı öldürmeler ve en az içme için Shadow (Spirit Tap, Mind Flay, Shadowform) olarak seviye atla. Discipline güçlü bir kalkanın arkasından Smite ve Penance ile seviye atlar; Holy zindan healer'ı ve tek başına daha yavaş."
L["Power in Light first: more Smite damage, your main attack as Discipline, on targets with your Holy Fire or Shadow Word: Pain."] = "Önce Power in Light: üstünde Holy Fire ya da Shadow Word: Pain olan hedeflerde, Discipline olarak ana saldırın Smite'a daha çok hasar."
L["Improved Power Word: Shield: a bigger shield is fewer interrupted casts and less healing."] = "Improved Power Word: Shield: daha büyük kalkan, daha az kesilen büyü ve daha az iyileştirme demek."
L["Penance is a channelled burst of Holy damage or healing: use it on every mob."] = "Penance kanallanan ani bir Holy hasarı ya da iyileştirmesi: her yaratıkta kullan."
L["Power Infusion is the capstone: a damage and healing cooldown for you or an ally."] = "Zirve yetenek Power Infusion: sana ya da bir müttefike hasar ve iyileştirme cooldown'ı."
L["The last 20 points go to Shadow: Spirit Tap's regen after kills, a longer Shadow Word: Pain, more Shadow hit, Mind Flay and a quicker Mind Blast."] = "Son 20 puan Shadow'a gider: öldürmelerden sonra Spirit Tap'in yenilenmesi, daha uzun Shadow Word: Pain, daha çok Shadow isabeti, Mind Flay ve daha sık Mind Blast."
L["Holy Specialization first: more crits on Smite and on your heals."] = "Önce Holy Specialization: Smite'ta ve iyileştirmelerinde daha çok kritik."
L["Divine Fury speeds up Smite, Holy Fire and your big heals."] = "Divine Fury; Smite, Holy Fire ve büyük iyileştirmelerini hızlandırır."
L["Spiritual Guidance adds 25% of your Spirit to your healing but only 8% to your damage: Spirit gear helps your heals most."] = "Spiritual Guidance, Spirit'inin %25'ini iyileştirmene ama yalnızca %8'ini hasarına ekler: Spirit ekipmanı en çok iyileştirmelerine yarar."
L["Prayer of Mending is the capstone: a heal that jumps between your group as they take damage."] = "Zirve yetenek Prayer of Mending: grubun hasar aldıkça üyeler arasında zıplayan bir iyileştirme."
L["The last 20 points go to Discipline: a stronger wand, a bigger Power Word: Shield, Meditation's regen while casting and more Intellect."] = "Son 20 puan Discipline'e gider: daha güçlü wand, daha büyük Power Word: Shield, Meditation'ın büyü yaparken yenilenmesi ve daha çok Intellect."
L["Mental Strength comes last: on Forever its points do not count toward the Discipline tiers."] = "Mental Strength en sona kalır: Forever'da puanları Discipline sıralarına sayılmaz."
L["Spirit Tap first: after each kill your regen jumps, so you drink far less."] = "Önce Spirit Tap: her öldürmeden sonra yenilenmen fırlar, böylece çok daha az içersin."
L["Mind Flay is your main damage and slow from here; Improved Mind Flay makes it hit harder."] = "Buradan sonra ana hasarın ve yavaşlatman Mind Flay; Improved Mind Flay onu daha sert vurdurur."
L["Vampiric Embrace heals you from your Shadow damage."] = "Vampiric Embrace, Shadow hasarından seni iyileştirir."
L["Shadowform is the capstone: more Shadow damage and less physical damage taken."] = "Zirve yetenek Shadowform: daha çok Shadow hasarı ve daha az alınan fiziksel hasar."
L["ForeverDB through level 30, Polestar after"] = "Seviye 30'a kadar ForeverDB, sonrasında Polestar"
L["Polestar, with ForeverDB's builds to level 20"] = "Polestar, seviye 20'ye kadar ForeverDB'nin planlarıyla"
L["Polestar, with ForeverDB's talent data"] = "Polestar, ForeverDB'nin yetenek verisiyle"
-- L["ForeverDB"] = ""
L["ForeverDB's leveling builds, adapted to level 30"] = "ForeverDB'nin seviye atlama planları, seviye 30'a uyarlanmış"

-- Dungeons/Dungeons.lua
L["Kill %d %s"] = "Öldür: %d %s"
L["Collect %s"] = "Topla: %s"
L["Collect %d %s"] = "Topla: %d %s"
L["Use %s"] = "Kullan: %s"
L["Dungeons in leveling guides"] = "Seviye rehberlerinde zindanlar"
L["Off: the guide skips this group quest and keeps to the solo route. Until you choose, it asks when it gets there."] = "Kapalıyken rehber bu grup görevini atlar ve tek başına rotada kalır. Sen seçene kadar oraya gelince sorar."
L["Group quests"] = "Grup görevleri"
L["Group quests in leveling guides"] = "Seviye rehberlerinde grup görevleri"
L["Tell me when a dungeon opens up"] = "Bir zindan açılınca bana söyle"
L["When a level-up opens a dungeon's quests to this character, a card on the guide window says so, once per dungeon, with a button that picks up its quests in a new tab."] = "Bir seviye atlaması bu karaktere bir zindanın görevlerini açtığında, rehber penceresindeki bir kart bunu her zindan için bir kez söyler; zindanın görevlerini yeni bir sekmede toplayan bir düğmeyle."
L["Entrance in Horde territory (outside the Undercity)"] = "Giriş Horde topraklarında (Undercity dışında)"
L["Entrance in Alliance territory (in Ironforge)"] = "Giriş Alliance topraklarında (Ironforge içinde)"
L["Entrance in Horde territory (in Orgrimmar)"] = "Giriş Horde topraklarında (Orgrimmar içinde)"
L["Entrance in Alliance territory (in Stormwind)"] = "Giriş Alliance topraklarında (Stormwind içinde)"
L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route. More dungeons join this list as they are added to the guides' route."] = "Seviye rehberleri, adımı olduğu yerde seni bu zindandan geçirir. Kapalıyken tek başına rotada kalırlar. Zindanlar rehberlerin rotasına eklendikçe bu listeye katılır."
L["Speak with %s"] = "Konuş: %s"

-- Dungeons/Attune.lua
L["Lets Lothos Riftwaker in Blackrock Mountain send you to the Molten Core; without it, walk in through Blackrock Depths."] = "Blackrock Mountain'daki Lothos Riftwaker'ın seni Molten Core'a göndermesini sağlar; olmadan Blackrock Depths üzerinden yürüyerek girersin."
L["Douses the Molten Core's runes; Majordomo Executus comes out only when every rune is doused. Duke Hydraxis hands it out once Hands of the Enemy is done."] = "Molten Core'un rünlerini söndürür; Majordomo Executus ancak tüm rünler sönünce ortaya çıkar. Duke Hydraxis, Hands of the Enemy görevi bitince bunu verir."
L["Everyone entering Onyxia's Lair carries the Drakefire Amulet."] = "Onyxia's Lair'e giren herkes Drakefire Amulet taşır."
L["Lets you touch the Orb of Command in Upper Blackrock Spire to reach Blackwing Lair; without it, walk in through the spire."] = "Blackwing Lair'e ulaşmak için Upper Blackrock Spire'daki Orb of Command'a dokunmanı sağlar; olmadan kulenin içinden yürüyerek girersin."
L["Everyone entering Naxxramas needs it; which of the three quests you take depends on your standing with the Argent Dawn."] = "Naxxramas'a giren herkese gerekir; üç görevden hangisini alacağın Argent Dawn ile itibarına bağlı."
L["Opens Scholomance's gate; one key opens it for the group."] = "Scholomance'ın kapısını açar; bir anahtar grup için açar."
L["Opens the Shadowforge gates in Blackrock Depths; one key opens them for the group."] = "Blackrock Depths'teki Shadowforge kapılarını açar; bir anahtar grup için açar."
L["Opens the cells of Blackrock Depths' prison."] = "Blackrock Depths hapishanesinin hücrelerini açar."
L["Opens the Eastwall Gate into Stratholme's Scourge-held districts."] = "Stratholme'un Scourge elindeki mahallelerine açılan Eastwall Gate'i açar."
L["Opens the inner doors of Dire Maul's North and West wings."] = "Dire Maul'un North ve West kanatlarının iç kapılarını açar."
L["Opens Gnomeregan's back door, the Workshop entrance."] = "Gnomeregan'ın arka kapısını, Workshop girişini açar."
L["Opens the doors of the Armory and the Cathedral."] = "Armory ve Cathedral'ın kapılarını açar."
L["Opens the gate of the Horde's way into the City of Dalaran; one key opens it for the group. The Alliance walks in through the sewer pipe in Cantrips & Crows."] = "Horde'un City of Dalaran'a giden yolunun kapısını açar; bir anahtar grup için açar. Alliance, Cantrips & Crows'daki kanalizasyon borusundan içeri yürür."

-- Nav/Handoff.lua
L["Hand guiding to Shortest Path Forever"] = "Yol göstermeyi Shortest Path Forever'a bırak"
L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay. Off: Polestar guides, and steps aside only while a journey you started in Shortest Path Forever runs."] = "Shortest Path Forever'ın oku, rotası ve yolculuğu seni her hedefe götürür. Polestar'ın oku, rota çizgileri, yolculuk adımları, yolculuk düğmesi, ulaşım uyarıları, harita tıklamaları ve /way devreden çıkar; rehber penceresi ve harita iğneleri kalır. Kapalı: Polestar yol gösterir, yalnızca Shortest Path Forever'da başlattığın bir yolculuk sürerken çekilir."

