L["Marks it with %s if it has no icon yet: you don't lead the party."] = "Henüz simgesi yoksa onu %s ile işaretler: grubun lideri değilsin."
L["Marks nothing: in a raid only the leader and assistants set icons."] = "Hiçbir şeyi işaretlemez: raidde simgeleri yalnızca lider ve yardımcılar koyar."
