L["You can take the quest this item starts. Click to read it."] = "Bu eşyanın başlattığı görevi alabilirsin. Okumak için tıkla."

-- Core/Import.lua
L["Imported"] = "İçe aktarılanlar"
L["This import string is damaged or incomplete. Copy the whole string again."] = "Bu içe aktarma metni bozuk ya da eksik. Metnin tamamını yeniden kopyala."
L["This import string needs a newer Polestar."] = "Bu içe aktarma metni daha yeni bir Polestar gerektiriyor."
L["This import string holds no guide."] = "Bu içe aktarma metninde rehber yok."
L["Its guide id %s must start with its author's own id, as in yendi/cozy-sleeping-bag."] = "Rehber kimliği %s, yazarın kendi kimliğiyle başlamalı; örneğin yendi/cozy-sleeping-bag."
L["Guides under %s/ come from the community addon %s, which is installed."] = "%s/ altındaki rehberler, yüklü olan %s topluluk eklentisinden geliyor."
L["Its guide has %d steps; an import string holds %d at most. A bigger guide comes as a community addon."] = "Rehberinde %d adım var; bir içe aktarma metni en fazla %d adım taşır. Daha büyük bir rehber topluluk eklentisi olarak gelir."
L["It leads on to %s, which is neither one of Polestar's guides nor an imported one: import that guide first."] = "Devamı %s, ama o ne Polestar'ın rehberlerinden ne de içe aktarılmış: önce o rehberi içe aktar."
L["This import string holds a field Polestar does not read (%s). It may need a newer Polestar."] = "Bu içe aktarma metninde Polestar'ın okumadığı bir alan var (%s). Daha yeni bir Polestar gerekebilir."
L["Paste an import string."] = "Bir içe aktarma metni yapıştır."
L["This import string is too long: Polestar reads up to %d characters."] = "Bu içe aktarma metni çok uzun: Polestar en fazla %d karakter okur."
L["This is not a Polestar import string."] = "Bu bir Polestar içe aktarma metni değil."
L["This game client cannot read import strings."] = "Bu oyun istemcisi içe aktarma metinlerini okuyamaz."
L["This import string holds a text longer than Polestar reads (%s): %d characters at most."] = "Bu içe aktarma metninde Polestar'ın okuyabileceğinden uzun bir metin var (%s): en fazla %d karakter."
L["This import string holds too much: Polestar reads up to %d KB of guide data."] = "Bu içe aktarma metni çok fazla veri taşıyor: Polestar en fazla %d KB rehber verisi okur."
L["Its guide has %d goals in step %d; an import string holds %d per step at most."] = "Rehberinde %2$d. adımda %1$d hedef var; bir içe aktarma metni adım başına en fazla %3$d hedef taşır."
L["Its guide has %d candidates in a goal; an import string holds %d per goal at most."] = "Rehberinde bir hedefte %d aday var; bir içe aktarma metni hedef başına en fazla %d aday taşır."
L["Its guide has more than one direct turn-in for quest %d in step %d."] = "Rehberinde %2$d. adımda %1$d numaralı görev için birden fazla doğrudan teslim var."
L["Its guide has a candidate coordinate outside 0-100."] = "Rehberinde 0-100 dışında bir aday koordinatı var."
L["Its guide has a spot coordinate outside 0-100."] = "Rehberinde 0-100 dışında bir nokta koordinatı var."
L["Its guide has a map frame with missing fields."] = "Rehberinde alanları eksik bir harita çerçevesi var."
L["Its guide has a degenerate map frame (zero extent)."] = "Rehberinde bozuk bir harita çerçevesi var (sıfır boyut)."
L["Its guide has a map frame with out-of-range coordinates."] = "Rehberinde koordinatları aralık dışında bir harita çerçevesi var."
L["No imported guides to remove."] = "Kaldırılacak içe aktarılmış rehber yok."
L["Removed %d imported guide(s)."] = "%d içe aktarılmış rehber kaldırıldı."
L["Usage: /polestar import delete <guide-id>"] = "Kullanım: /polestar import delete <rehber-kimliği>"
L["Removed imported guide %s."] = "İçe aktarılmış rehber kaldırıldı: %s."
L["No imported guide with id %s."] = "%s kimlikli içe aktarılmış rehber yok."
L["Open the Import page; import clear / import delete <id>: remove imports"] = "İçe aktar sayfasını aç; import clear / import delete <id>: içe aktarılanları kaldır"
L["Its guide has %d entries in %s; an import string holds %d there at most."] = "Rehberinde %2$s içinde %1$d girdi var; bir içe aktarma metni orada en çok %3$d tutar."

