L["You have version %s of this guide. Update replaces it and keeps your progress where its steps are unchanged."] = "Bu rehberin %s sürümü sende var. Güncelle onu değiştirir ve adımları değişmeyen yerlerde ilerlemeni korur."
L["This guide is already imported, at this version."] = "Bu rehber zaten bu sürümle içe aktarılmış."
