L["Updated %s."] = "Güncellendi: %s."
L["Imported %s. Find it in the guide menu under Community guides, Imported."] = "İçe aktarıldı: %s. Rehber menüsünde Topluluk rehberleri, İçe aktarılanlar altında bulabilirsin."
L["Paste an import string here (Ctrl+V)"] = "Buraya bir içe aktarma metni yapıştır (Ctrl+V)"
L["Delete"] = "Sil"
L["Two ways to bring someone else's guides into Polestar. Pick the one that fits."] = "Başkasının rehberlerini Polestar'a getirmenin iki yolu var. Uygun olanı seç."
L["Import string"] = "İçe aktarma metni"
L["One small guide: a quest chain, an item, a mount, an errand."] = "Tek küçük bir rehber: bir görev zinciri, bir eşya, bir binek, bir iş."
L["Its author shares it as text, anywhere. Paste it below."] = "Yazarı onu herhangi bir yerde metin olarak paylaşır. Aşağıya yapıştır."
L["Updates: paste the newer string, then Update."] = "Güncellemeler: yeni metni yapıştır, sonra Güncelle."
L["One guide of up to %d steps."] = "En fazla %d adımlık tek bir rehber."
L["Community addon"] = "Topluluk eklentisi"
L["A whole route or a set of guides: a leveling route, every profession."] = "Bütün bir rota ya da bir rehber seti: bir seviye rotası, tüm meslekler."
L["Install it like any addon, then restart the game."] = "Her eklenti gibi kur, sonra oyunu yeniden başlat."
L["Updates: your addon app updates it."] = "Güncellemeler: eklenti uygulaman günceller."
L["No size limit."] = "Boyut sınırı yok."
L["Paste a string"] = "Bir metin yapıştır"
L["Import"] = "İçe aktar"
L["No imported guides yet."] = "Henüz içe aktarılmış rehber yok."
L["Want more than one guide?"] = "Birden fazla rehber mi istiyorsun?"
L["A set of guides, or one too big for a string, comes as a community addon:"] = "Bir rehber seti ya da bir metne sığmayacak kadar büyük bir rehber, topluluk eklentisi olarak gelir:"
L["Get it from wherever its author publishes it."] = "Yazarı nerede yayımlıyorsa oradan al."
L["Its guides appear in the guide menu under Community guides, with the author's name. Options, Community guides turns it on or off."] = "Rehberleri, rehber menüsünde Topluluk rehberleri altında yazarın adıyla görünür. Seçenekler, Topluluk rehberleri onu açar ya da kapatır."
L["Update"] = "Güncelle"
L["Your imported guides"] = "İçe aktardığın rehberler"
L["version %s"] = "sürüm %s"
L["Guides someone shared with you, as an import string or a community addon."] = "Birinin seninle içe aktarma metni ya da topluluk eklentisi olarak paylaştığı rehberler."
L["The author differs from the stored guide's."] = "Yazar, kayıtlı rehberinkinden farklı."
L["The licence differs from the stored guide's."] = "Lisans, kayıtlı rehberinkinden farklı."

