-- UI/LineStyle.lua
L["Dots"] = "Noktalar"
L["Sparkle"] = "Işıltı"
L["Intensity"] = "Yoğunluk"
L["How bright each sparkle and its glow are."] = "Her ışıltının ve parıltısının ne kadar parlak olduğu."
L["Density"] = "Sıklık"
L["How close together the sparkles sit, the same at any zoom."] = "Işıltıların birbirine ne kadar yakın durduğu; her yakınlaştırmada aynı."
L["Smaller, dimmer, calmer twinkles that drift less; no glow at 100%."] = "Daha küçük, daha soluk, daha sakin ve daha az süzülen pırıltılar; %100'de parıltı yok."
L["Sparkle size"] = "Işıltı boyutu"
L["Each sparkle's size before subtlety."] = "Her ışıltının, sadelik uygulanmadan önceki boyutu."
L["Flow toward goal"] = "Hedefe akış"
L["How fast the sparkles drift toward the goal; 0 holds them still."] = "Işıltıların hedefe ne kadar hızlı süzüldüğü; 0 onları sabit tutar."
L["Most sparkles shown"] = "En fazla ışıltı"
L["A ceiling on each map, whatever the density."] = "Sıklık ne olursa olsun her harita için bir üst sınır."
L["Sparkle colour"] = "Işıltı rengi"
L["Loot gold is the colour of the game's own loot sparkle. Route colours tint each leg as the dots are."] = "Loot altını, oyunun kendi loot ışıltısının rengi. Rota renkleri her bacağı noktalardaki gibi renklendirir."
L["Loot gold"] = "Loot altını"
L["Arcane blue"] = "Arcane mavisi"
L["Fel green"] = "Fel yeşili"
L["Rose"] = "Gül"
L["Starlight"] = "Yıldız ışığı"
L["Route colours"] = "Rota renkleri"
L["Whole route"] = "Tüm rota"
L["Sparkle the legs after this one too, fainter. Off: only the leg you are on."] = "Bundan sonraki bacaklar da daha soluk ışıldasın. Kapalı: yalnızca bulunduğun bacak."
L["Subtle"] = "Sade"
L["Dazzling"] = "Göz alıcı"
L["Route line style"] = "Rota çizgisi stili"
L["Route colours tint each leg by how you travel it. Cyan, magenta and white stand apart from the minimap's yellow herb and ore dots and its gold quest marks. Right-click to reset."] = "Rota renkleri her bacağı nasıl gittiğine göre renklendirir. Camgöbeği, macenta ve beyaz, mini haritanın sarı bitki ve maden noktalarından ve altın görev işaretlerinden ayrışır. Sıfırlamak için sağ tıkla."
L["Cyan"] = "Camgöbeği"
L["Magenta"] = "Macenta"
L["White"] = "Beyaz"
L["Minimap opacity"] = "Mini harita opaklığı"
L["Minimap size"] = "Mini harita boyutu"
L["Line thickness"] = "Çizgi kalınlığı"
L["How thick the solid line is on the world map; the minimap's follows its size. Right-click to reset."] = "Düz çizginin dünya haritasındaki kalınlığı; mini haritadaki kendi boyutunu izler. Sıfırlamak için sağ tıkla."
